  it('builds reusable timeline snap points and resolves the closest edit target', () => {
    const project = createDefaultEditorProject();
    const snapPoints = buildTimelineSnapPoints(project, {
      excludeClipId: 'clip-interview-1',
      extraPoints: [42, Number.NaN],
      playhead: 7,
    });

    expect(snapPoints).toEqual(expect.arrayContaining([
      { time: 0, type: 'project-start' },
      { time: project.duration, type: 'project-end' },
      { time: 7, type: 'playhead' },
      { time: 42, type: 'extra' },
      expect.objectContaining({ time: 32, type: 'clip-start', clipId: 'clip-interview-2', trackId: 'track-v1' }),
    ]));
    expect(snapPoints.some((point) => point.clipId === 'clip-interview-1')).toBe(false);
    expect(resolveTimelineSnap({
      targetTime: 41.93,
      threshold: 0.2,
      snapPoints,
    })).toMatchObject({
      snappedTime: 42,
      snapPoint: { time: 42, type: 'extra' },
    });
    expect(snapTimelineTime({
      project,
      time: 32.08,
      threshold: 0.2,
    })).toMatchObject({
      snappedTime: 32,
      snapPoint: expect.objectContaining({ type: 'clip-start', clipId: 'clip-interview-2' }),
    });
  });

  it('resolves timeline placement compatibility and track availability', () => {
    const project = createDefaultEditorProject();
    const videoTrack = project.tracks.find((track) => track.id === 'track-v1')!;
    const audioTrack = project.tracks.find((track) => track.id === 'track-a1')!;

    expect(canPlaceClipKindOnTrack('image', 'video')).toBe(true);
    expect(canPlaceClipKindOnTrack('audio', 'video')).toBe(false);
    expect(canPlaceTimeSpansOnTrack({
      track: videoTrack,
      timeSpans: [{ start: 70, duration: 4 }],
    })).toBe(true);
    expect(canPlaceTimeSpansOnTrack({
      track: videoTrack,
      timeSpans: [{ start: 6, duration: 4 }],
    })).toBe(false);
    expect(canPlaceTimeSpansOnTrack({
      track: videoTrack,
      timeSpans: [{ start: 6, duration: 4, excludeClipId: 'clip-interview-1' }],
    })).toBe(true);
    expect(canPlaceTimeSpansTogether([
      { start: 10, duration: 5 },
      { start: 14, duration: 3 },
    ])).toBe(false);
    expect(resolveTimelineTrackPlacement({
      project,
      trackKind: 'audio',
      timeSpans: [{ start: 92, duration: 4 }],
      strategy: { type: 'explicit', trackId: audioTrack.id },
    })).toMatchObject({
      kind: 'existingTrack',
      trackId: audioTrack.id,
      trackKind: 'audio',
    });
    expect(resolveTimelineTrackPlacement({
      project,
      trackKind: 'video',
      timeSpans: [{ start: 6, duration: 4 }],
      strategy: { type: 'explicit', trackId: videoTrack.id },
    })).toBeNull();
    expect(resolveTimelineTrackPlacement({
      project,
      trackKind: 'video',
      timeSpans: [{ start: 6, duration: 4 }],
      strategy: { type: 'firstAvailable' },
    })).toMatchObject({
      kind: 'existingTrack',
      trackId: 'track-v2',
      trackKind: 'video',
    });
  });

  it('resolves grouped timeline move offsets, collision clamps, and target track placement', () => {
    const project = createDefaultEditorProject();
    const group = buildTimelineMoveGroup({
      project,
      clipIds: ['clip-interview-1', 'clip-ai-city'],
      anchorClipId: 'clip-interview-1',
    });

    expect(group?.members.map((member) => ({ id: member.clip.id, offset: member.timeOffset }))).toEqual([
      { id: 'clip-interview-1', offset: 0 },
      { id: 'clip-ai-city', offset: 18 },
    ]);

    const movedGroup = resolveTimelineGroupMoveFromProject({
      project,
      clipIds: ['clip-interview-1', 'clip-ai-city'],
      anchorClipId: 'clip-interview-1',
      requestedAnchorStart: 4,
      preventOverlap: true,
    });
    expect(movedGroup).toMatchObject({
      appliedDelta: 4,
      appliedAnchorStart: 4,
      constrained: false,
    });
    expect(movedGroup?.movedClips.map((clip) => ({ id: clip.id, start: clip.start, trackId: clip.trackId }))).toEqual([
      { id: 'clip-interview-1', start: 4, trackId: 'track-v1' },
      { id: 'clip-ai-city', start: 22, trackId: 'track-v2' },
    ]);

    const clampedMove = resolveTimelineGroupMoveFromProject({
      project,
      clipIds: ['clip-interview-2'],
      anchorClipId: 'clip-interview-2',
      requestedAnchorStart: 0,
      preventOverlap: true,
    });
    expect(clampedMove).toMatchObject({
      appliedDelta: -4,
      appliedAnchorStart: 28,
      constrained: true,
    });

    expect(resolveTimelineGroupMoveFromProject({
      project,
      clipIds: ['clip-interview-2'],
      anchorClipId: 'clip-interview-2',
      requestedAnchorStart: 50,
      targetTrackId: 'track-v2',
    })?.movedClips[0]).toMatchObject({
      id: 'clip-interview-2',
      trackId: 'track-v2',
      start: 50,
    });
    expect(resolveTimelineGroupMoveFromProject({
      project,
      clipIds: ['clip-interview-2'],
      anchorClipId: 'clip-interview-2',
      requestedAnchorStart: 18,
      targetTrackId: 'track-v2',
    })).toBeNull();

    const newTrackPlan = resolveTimelineGroupMoveFromProject({
      project,
      clipIds: ['clip-interview-2'],
      anchorClipId: 'clip-interview-2',
      requestedAnchorStart: 50,
      newTrackPosition: 'above',
    });
    expect(newTrackPlan).toMatchObject({
      targetTrackId: 'track-video-3',
      newTrack: {
        id: 'track-video-3',
        name: 'Video 3',
        kind: 'video',
        insertIndex: 0,
        position: 'above',
      },
    });
    expect(newTrackPlan?.movedClips[0]).toMatchObject({
      id: 'clip-interview-2',
      trackId: 'track-video-3',
      start: 50,
    });
    expect(resolveTimelineGroupMoveFromProject({
      project,
      clipIds: ['clip-interview-1', 'clip-ai-city'],
      anchorClipId: 'clip-interview-1',
      requestedAnchorStart: 0,
      newTrackPosition: 'above',
    })).toBeNull();

    const movedToNewTrackProject = moveClipsToNewTrackAtTime(project, ['clip-interview-2'], 'above', 50, {
      anchorClipId: 'clip-interview-2',
    });
    expect(movedToNewTrackProject.tracks.map((track) => track.id).slice(0, 3)).toEqual(['track-video-3', 'track-v1', 'track-v2']);
    expect(movedToNewTrackProject.tracks[0]).toMatchObject({
      id: 'track-video-3',
      name: 'Video 3',
      kind: 'video',
    });
    expect(movedToNewTrackProject.tracks[0].clips).toHaveLength(1);
    expect(movedToNewTrackProject.tracks[0].clips[0]).toMatchObject({
      id: 'clip-interview-2',
      trackId: 'track-video-3',
      start: 50,
    });
    expect(movedToNewTrackProject.tracks.find((track) => track.id === 'track-v1')?.clips.map((clip) => clip.id)).toEqual(['clip-interview-1']);
  });

  it('resolves grouped timeline resize bounds and trim clamp compatibility', () => {
    const project = createDefaultEditorProject();
    const endGroup = buildTimelineResizeGroup({
      project,
      clipIds: ['clip-interview-1'],
      edge: 'end',
    });

    expect(endGroup).toMatchObject({
      minTimelineTime: 0.25,
      maxTimelineTime: 32,
      minDelta: -27.75,
      maxDelta: 4,
    });

    const tailClamp = resolveTimelineResizeTimeFromProject({
      project,
      clipIds: ['clip-interview-1'],
      edge: 'end',
      timelineTime: 40,
    });
    expect(tailClamp).toMatchObject({
      appliedTimelineTime: 32,
      constrained: true,
    });
    expect(clampClipTrimTime(project, ['clip-interview-1'], 'end', 40)).toBe(32);

    const headClamp = resolveTimelineResizeTimeFromProject({
      project,
      clipIds: ['clip-interview-2'],
      edge: 'start',
      timelineTime: 20,
    });
    expect(headClamp).toMatchObject({
      appliedTimelineTime: 28,
      constrained: true,
    });
    expect(clampClipTrimTime(project, ['clip-interview-2'], 'start', 20)).toBe(28);

    const deltaPlan = resolveTimelineGroupResizeFromProject({
      project,
      clipIds: ['clip-interview-1', 'clip-ai-city'],
      edge: 'end',
      anchorClipId: 'clip-interview-1',
      requestedAnchorTimelineTime: 40,
    });
    expect(deltaPlan).toMatchObject({
      requestedDelta: 12,
      appliedDelta: 4,
      appliedAnchorTimelineTime: 32,
      constrained: true,
    });
    expect(deltaPlan?.updates.map((update) => ({
      clipId: update.clipId,
      appliedTimelineTime: update.appliedTimelineTime,
    }))).toEqual([
      { clipId: 'clip-interview-1', appliedTimelineTime: 32 },
      { clipId: 'clip-ai-city', appliedTimelineTime: 30 },
    ]);
  });

  it('resolves numeric keyframes through the shared interpolation module', () => {
    expect(interpolateNumericKeyframes([
      { time: 0, value: 0, easing: 'linear' },
      { time: 10, value: 10, easing: 'linear' },
    ], 5, 99, { round: true })).toBe(5);
    expect(interpolateNumericKeyframes([
      { time: 0, value: 0, easing: 'smooth' },
      { time: 10, value: 10, easing: 'linear' },
    ], 2.5, 99, { round: true })).toBe(1.563);
    expect(interpolateNumericKeyframes([
      { time: 0, value: 0, easing: 'easeIn' },
      { time: 10, value: 10, easing: 'linear' },
    ], 5, 99, { round: true })).toBe(2.5);
    expect(interpolateNumericKeyframes([
      { time: 0, value: 0, easing: 'easeOut' },
      { time: 10, value: 10, easing: 'linear' },
    ], 5, 99, { round: true })).toBe(7.5);
    expect(interpolateNumericKeyframes([
      { time: 0, value: 0, easing: 'easeInOut' },
      { time: 10, value: 10, easing: 'linear' },
    ], 2.5, 99, { round: true })).toBe(1.563);
    expect(interpolateNumericKeyframes([
      { time: 0, value: 2, easing: 'hold' },
      { time: 10, value: 10, easing: 'linear' },
    ], 5, 99, { round: true })).toBe(2);
    expect(interpolateNumericKeyframes([], 5, 7, { min: 0, max: 1, round: true })).toBe(1);

    const project = createDefaultEditorProject();
    const opacityKeyframes: ClipKeyframe[] = [
      { id: 'kf-shared-opacity-start', property: 'opacity', time: 0, value: 0, easing: 'linear' },
      { id: 'kf-shared-opacity-end', property: 'opacity', time: 10, value: 1, easing: 'smooth' },
    ];
    const keyframedProject: EditorProject = {
      ...project,
      tracks: project.tracks.map((track) => ({
        ...track,
        clips: track.clips.map((clip) => (
          clip.id === 'clip-interview-1'
            ? { ...clip, keyframes: opacityKeyframes }
            : clip
        )),
      })),
    };
    const clip = keyframedProject.tracks[0].clips.find((candidate) => candidate.id === 'clip-interview-1')!;
    const samples = toNumericKeyframeSamples(clip.keyframes, 'opacity');

    expect(samples.map((sample) => sample.time)).toEqual([0, 10]);
    expect(resolveClipNumericKeyframeValue(clip, 'opacity', 5, clip.opacity, { min: 0, max: 1, round: true })).toBe(0.5);
    expect(buildProgramPreviewStack(keyframedProject, 5).primaryLayer?.style.opacity).toBe(0.5);

    const splitProject = splitClip(keyframedProject, 'clip-interview-1', 5);
    const splitLeftClip = splitProject.tracks[0].clips.find((candidate) => candidate.id === 'clip-interview-1');
    const splitRightClip = splitProject.tracks[0].clips.find((candidate) => candidate.id.startsWith('clip-interview-1-split-'));
    expect(splitLeftClip?.keyframes.find((keyframe) => keyframe.property === 'opacity' && keyframe.time === 5)).toMatchObject({
      value: 0.5,
    });
    expect(splitRightClip?.keyframes.find((keyframe) => keyframe.property === 'opacity' && keyframe.time === 0)).toMatchObject({
      value: 0.5,
    });
  });

  it('summarizes mixed and common values for multi-clip inspector editing', () => {
    const project = createDefaultEditorProject();
    const clips = project.tracks.flatMap((track) => track.clips);
    const interview1 = clips.find((clip) => clip.id === 'clip-interview-1');
    const interview2 = clips.find((clip) => clip.id === 'clip-interview-2');
    const summary = summarizeClipSelectionProperties([interview1!, interview2!]);
    const matchedProject = updateClips(project, ['clip-interview-1', 'clip-interview-2'], {
      color: '#00cc88',
      volume: 0.75,
      opacity: 0.5,
      blendMode: 'screen',
      reversed: true,
    });
    const matchedSummary = summarizeClipSelectionProperties(
      matchedProject.tracks[0].clips.filter((clip) => clip.id === 'clip-interview-1' || clip.id === 'clip-interview-2'),
    );

    expect(summary.color.mixed).toBe(true);
    expect(summary.color.value).toBeUndefined();
    expect(summary.volume).toMatchObject({ mixed: false, value: 1, count: 2 });
    expect(summary.blendMode).toMatchObject({ mixed: false, value: 'normal' });
    expect(summary.locked).toMatchObject({ mixed: false, value: false });
    expect(matchedSummary.color).toMatchObject({ mixed: false, value: '#00cc88' });
    expect(matchedSummary.volume).toMatchObject({ mixed: false, value: 0.75 });
    expect(matchedSummary.opacity).toMatchObject({ mixed: false, value: 0.5 });
    expect(matchedSummary.blendMode).toMatchObject({ mixed: false, value: 'screen' });
    expect(matchedSummary.reversed).toMatchObject({ mixed: false, value: true });
  });

