  it('steps JKL shuttle playback rates and clamps playback time', () => {
    expect(stepShuttleRate(0, 'forward')).toBe(1);
    expect(stepShuttleRate(1, 'forward')).toBe(2);
    expect(stepShuttleRate(2, 'forward')).toBe(4);
    expect(stepShuttleRate(4, 'forward')).toBe(4);
    expect(stepShuttleRate(0, 'reverse')).toBe(-1);
    expect(stepShuttleRate(-1, 'reverse')).toBe(-2);
    expect(stepShuttleRate(-2, 'reverse')).toBe(-4);
    expect(stepShuttleRate(-4, 'reverse')).toBe(-4);
    expect(stepShuttleRate(4, 'stop')).toBe(0);

    expect(advancePlaybackTime(10, 20, 2, 0.5)).toBe(11);
    expect(advancePlaybackTime(1, 20, -4, 0.5)).toBe(0);
    expect(advancePlaybackTime(19.8, 20, 4, 0.1)).toBe(20);
    expect(isPlaybackAtBoundary(20, 20, 1)).toBe(true);
    expect(isPlaybackAtBoundary(0, 20, -1)).toBe(true);

    expect(advancePlaybackTime(4.9, 20, 2, 0.2, { loopRange: { start: 2, end: 5 } })).toBe(2.3);
    expect(advancePlaybackTime(2.1, 20, -2, 0.2, { loopRange: { start: 2, end: 5 } })).toBe(4.7);
    expect(advancePlaybackTime(12, 20, 1, 0.1, { loopRange: { start: 2, end: 5 } })).toBe(2);
    expect(advancePlaybackTime(12, 20, -1, 0.1, { loopRange: { start: 2, end: 5 } })).toBe(5);
    expect(isPlaybackAtBoundary(5, 20, 1, { loopRange: { start: 2, end: 5 } })).toBe(false);

    expect(resolveShuttlePlaybackRate(2, 'forward')).toBe(4);
    expect(resolveShuttlePlaybackRate(-2, 'stop')).toBe(0);
    expect(resolveProgramPlaybackToggleRate(0)).toBe(1);
    expect(resolveProgramPlaybackToggleRate(1)).toBe(0);
    expect(resolveProgramPlaybackRateState(1)).toEqual({
      timelinePlaybackRate: 1,
      isPlaying: true,
      activeMonitor: 'program',
    });
    expect(resolveProgramPlaybackRateState(0)).toEqual({
      timelinePlaybackRate: 0,
      isPlaying: false,
      activeMonitor: 'program',
    });
    expect(resolvePlaybackFrameElapsedSeconds(undefined, 1000)).toBe(0);
    expect(resolvePlaybackFrameElapsedSeconds(1000, 1400)).toBe(0.25);
    expect(resolvePlaybackFrameElapsedSeconds(1000, 1120)).toBe(0.12);
    expect(resolvePlaybackFrameElapsedSeconds(1000, 900)).toBe(0);

    expect(resolvePlaybackFrameState({
      currentPlayhead: 19.8,
      duration: 20,
      playbackRate: 4,
      elapsedSeconds: 0.1,
    })).toEqual({
      playhead: 20,
      playbackRate: 0,
      isPlaying: false,
      shouldStop: true,
    });
    expect(resolvePlaybackFrameState({
      currentPlayhead: 4.9,
      duration: 20,
      playbackRate: 2,
      elapsedSeconds: 0.2,
      loopRange: { start: 2, end: 5 },
    })).toEqual({
      playhead: 2.3,
      playbackRate: 2,
      isPlaying: true,
      shouldStop: false,
    });
  });

  it('tracks preview frame drops for Program Monitor diagnostics', () => {
    const initial = buildPreviewFrameTelemetry({
      totalVideoFrames: 100,
      droppedVideoFrames: 1,
      timestampMs: 1000,
    });
    expect(initial.status).toBe('smooth');
    expect(initial.dropRate).toBe(0.01);

    const warning = buildPreviewFrameTelemetry({
      totalVideoFrames: 160,
      droppedVideoFrames: 4,
      timestampMs: 1500,
    }, initial);
    expect(warning.status).toBe('warning');
    expect(warning.droppedFrameDelta).toBe(3);

    const dropping = buildPreviewFrameTelemetry({
      totalVideoFrames: 200,
      droppedVideoFrames: 14,
      timestampMs: 2000,
    }, warning);
    expect(dropping.status).toBe('dropping');
    expect(dropping.label).toContain('25% dropped');

    const aggregate = aggregatePreviewFrameTelemetry([
      warning,
      buildPreviewFrameTelemetry({ totalVideoFrames: 80, droppedVideoFrames: 0, timestampMs: 1600 }),
    ]);
    expect(aggregate.status).toBe('warning');
    expect(aggregate.totalFrames).toBe(240);
    expect(aggregate.droppedFrames).toBe(4);

    const videoCallbackSample = buildPreviewFrameSampleFromVideoCallback({
      presentedFrames: 240,
      mediaTime: 12.5,
      expectedDisplayTime: 2100,
      processingDuration: 0.006,
    }, 2110);
    expect(videoCallbackSample).toMatchObject({
      totalVideoFrames: 240,
      presentedFrames: 240,
      mediaTimeSeconds: 12.5,
      expectedDisplayTimeMs: 2100,
      processingDurationMs: 6,
      timestampMs: 2110,
    });
    expect(buildPreviewFrameTelemetry(videoCallbackSample, dropping)).toMatchObject({
      totalFrames: 240,
      totalFrameDelta: 40,
      droppedFrameDelta: 0,
      status: 'smooth',
    });
  });

  it('builds video scopes from sampled RGBA frames', () => {
    const sample = buildVideoScopeSampleFromRgba([
      0, 0, 0, 255,
      255, 255, 255, 255,
      255, 0, 0, 255,
      0, 0, 255, 255,
    ], 2, 2, {
      histogramBins: 4,
      waveformColumns: 2,
      vectorscopeBins: 8,
    });

    expect(sample).toMatchObject({
      width: 2,
      height: 2,
      sampledPixels: 4,
      histogram: [0.75, 0, 0, 0.25],
      rgbHistogram: {
        red: [0.5, 0, 0, 0.5],
        green: [0.75, 0, 0, 0.25],
        blue: [0.5, 0, 0, 0.5],
      },
      waveform: [0.106, 0.536],
      rgbWaveform: {
        red: [0.5, 0.5],
        green: [0, 0.5],
        blue: [0, 1],
      },
      averageLuma: 0.321,
      peakLuma: 1,
      lowLuma: 0,
    });
    expect(sample.vectorscope.length).toBeGreaterThan(0);
    expect(sample.vectorscope.every((point) => (
      point.x >= -1
      && point.x <= 1
      && point.y >= -1
      && point.y <= 1
      && point.intensity > 0
      && point.intensity <= 1
    ))).toBe(true);
    const clippingReadout = resolveVideoScopeReadout(sample);
    expect(clippingReadout).toMatchObject({
      status: 'clipped',
      label: 'Clipping',
      shadowShare: 0.75,
      highlightShare: 0.25,
    });
    expect(formatVideoScopeSceneReadout(clippingReadout)).toContain('Clipping: Highlights and shadows are clipping');

    const balanced = buildVideoScopeSampleFromRgba([
      64, 64, 64, 255,
      128, 128, 128, 255,
      160, 160, 160, 255,
      192, 192, 192, 255,
    ], 2, 2, { histogramBins: 8, waveformColumns: 2 });
    expect(resolveVideoScopeReadout(balanced)).toMatchObject({
      status: 'balanced',
      label: 'Balanced',
    });

    const flat = buildVideoScopeSampleFromRgba([
      124, 124, 124, 255,
      128, 128, 128, 255,
      132, 132, 132, 255,
      136, 136, 136, 255,
    ], 2, 2, { histogramBins: 8, waveformColumns: 2 });
    expect(resolveVideoScopeReadout(flat)).toMatchObject({
      status: 'low-contrast',
      label: 'Flat',
      warning: 'Scene has low contrast; review levels or curves before final export.',
    });
    expect(formatVideoScopeSceneReadout(null)).toBe('No sampled frame');
  });

