  it('detaches embedded video audio into an editable audio clip and can relink it', () => {
    const project = createDefaultEditorProject();
    const detachedProject = detachEmbeddedAudio(project, 'clip-interview-1');
    const sourceClip = detachedProject.tracks[0].clips.find((clip) => clip.id === 'clip-interview-1');
    const detachedAudioClip = detachedProject.tracks
      .flatMap((track) => track.clips)
      .find((clip) => clip.kind === 'audio' && clip.automationTags.includes('linked-video:clip-interview-1'));

    expect(sourceClip?.automationTags).toEqual(expect.arrayContaining(['embedded-audio:disabled']));
    expect(detachedAudioClip).toMatchObject({
      assetId: 'asset-interview',
      start: 0,
      duration: 28,
      sourceIn: 0,
      speed: sourceClip?.speed,
      volume: sourceClip?.volume,
    });

    const detachedStack = buildProgramPreviewStack(detachedProject, 6);
    expect(detachedStack.audioLayers.map((layer) => layer.clip.id)).toEqual(['clip-music-1', detachedAudioClip?.id]);

    const detachedPlan = buildFfmpegRenderPlan(detachedProject, 'profile-youtube-4k');
    const sourceInput = detachedPlan.inputs.find((input) => input.clipId === 'clip-interview-1');
    const detachedInput = detachedPlan.inputs.find((input) => input.clipId === detachedAudioClip?.id);
    expect(sourceInput).toBeDefined();
    expect(detachedInput).toBeDefined();
    expect(detachedPlan.filterGraph.some((filter) => filter.startsWith(`[${sourceInput?.index}:a]`))).toBe(false);
    expect(detachedPlan.filterGraph.some((filter) => filter.startsWith(`[${detachedInput?.index}:a]`))).toBe(true);
    expect(detachedPlan.filterGraph.some((filter) => filter.includes('loudnorm=I=-14:TP=-1.5:LRA=11'))).toBe(true);

    const relinkedProject = relinkDetachedAudio(detachedProject, detachedAudioClip?.id ?? '');
    const relinkedSourceClip = relinkedProject.tracks[0].clips.find((clip) => clip.id === 'clip-interview-1');
    expect(relinkedSourceClip?.automationTags.includes('embedded-audio:disabled')).toBe(false);
    expect(relinkedProject.tracks.flatMap((track) => track.clips).some((clip) => clip.id === detachedAudioClip?.id)).toBe(false);
    expect(buildProgramPreviewStack(relinkedProject, 6).audioLayers.map((layer) => layer.clip.id)).toEqual(['clip-interview-1', 'clip-music-1']);
  });

  it('applies audio fade keyframes through preview and FFmpeg render volume automation', () => {
    const project = createDefaultEditorProject();
    const fadedProject = applyAudioFade(project, 'clip-music-1', 'both', 2);
    const fadedClip = fadedProject.tracks.find((track) => track.id === 'track-a1')?.clips.find((clip) => clip.id === 'clip-music-1');
    const volumeKeyframes = fadedClip?.keyframes.filter((keyframe) => keyframe.property === 'volume') ?? [];

    expect(volumeKeyframes.map((keyframe) => ({ time: keyframe.time, value: keyframe.value }))).toEqual([
      { time: 0, value: 0 },
      { time: 2, value: 1 },
      { time: 90, value: 1 },
      { time: 92, value: 0 },
    ]);
    expect(resolveTimelineClipVolumeEnvelope(fadedClip!)).toEqual([
      { time: 0, position: 0, value: 0 },
      { time: 2, position: 0.022, value: 1 },
      { time: 90, position: 0.978, value: 1 },
      { time: 92, position: 1, value: 0 },
    ]);
    expect(resolveTimelineClipVolumeEnvelope({
      ...fadedClip!,
      keyframes: [],
      volume: 0.5,
    })).toEqual([
      { time: 0, position: 0, value: 0.5 },
      { time: 92, position: 1, value: 0.5 },
    ]);
    expect(resolveTimelineClipVolumeEnvelope({
      ...fadedClip!,
      duration: 4,
      keyframes: [
        { id: 'kf-volume-ease-out-start', property: 'volume', time: 0, value: 0, easing: 'easeOut' },
        { id: 'kf-volume-ease-out-end', property: 'volume', time: 4, value: 1, easing: 'linear' },
      ],
    })).toEqual([
      { time: 0, position: 0, value: 0 },
      { time: 1, position: 0.25, value: 0.438 },
      { time: 2, position: 0.5, value: 0.75 },
      { time: 3, position: 0.75, value: 0.938 },
      { time: 4, position: 1, value: 1 },
    ]);
    expect(buildProgramPreviewStack(fadedProject, 1).audioLayers.find((layer) => layer.clip.id === 'clip-music-1')?.style.volume).toBe(0.158);
    expect(buildProgramPreviewStack(fadedProject, 91).audioLayers.find((layer) => layer.clip.id === 'clip-music-1')?.style.volume).toBe(0.5);

    const plan = buildFfmpegRenderPlan(fadedProject, 'profile-youtube-4k');
    expect(plan.filterGraph.some((filter) => (
      filter.includes("volume='") &&
      filter.includes('lte(t,2)') &&
      filter.includes('lte(t,90)') &&
      filter.includes('lte(t,92)')
    ))).toBe(true);
    expect(() => applyAudioFade(project, 'clip-ai-city', 'in', 1)).toThrow('Selected clip has no timeline audio.');

    const batchFadeResult = applyAudioFadeToClips(project, ['clip-music-1', 'clip-interview-1', 'clip-ai-city'], 'in', 1.5);
    const batchInterviewAudioFade = batchFadeResult.project.tracks[0].clips.find((clip) => clip.id === 'clip-interview-1');
    const batchMusicAudioFade = batchFadeResult.project.tracks[3].clips.find((clip) => clip.id === 'clip-music-1');
    expect(batchFadeResult.updatedClipIds).toEqual(['clip-interview-1', 'clip-music-1']);
    expect(batchFadeResult.skipped).toEqual([{ clipId: 'clip-ai-city', reason: 'Selected clip has no timeline audio.' }]);
    expect(batchInterviewAudioFade?.keyframes.filter((keyframe) => keyframe.property === 'volume').map((keyframe) => ({ time: keyframe.time, value: keyframe.value }))).toEqual([
      { time: 0, value: 0 },
      { time: 1.5, value: 1 },
    ]);
    expect(batchMusicAudioFade?.keyframes.filter((keyframe) => keyframe.property === 'volume').map((keyframe) => ({ time: keyframe.time, value: keyframe.value }))).toEqual([
      { time: 0, value: 0 },
      { time: 1.5, value: 1 },
    ]);
    expect(() => applyAudioFadeToClips(project, ['clip-ai-city'], 'in', 1)).toThrow('No selected clips could receive audio fade');
    expect(() => applyAudioFadeToClips(project, [], 'in', 1)).toThrow('No target clips selected.');
    const lockedAudioFadeProject = updateClip(project, 'clip-music-1', { locked: true });
    expect(() => applyAudioFadeToClips(lockedAudioFadeProject, ['clip-music-1'], 'in', 1)).toThrow('Cannot edit audio fades on a locked track or clip.');
  });

