  it('syncs selected external audio to video audio by waveform correlation', () => {
    const base = createDefaultEditorProject();
    const referenceAsset = {
      ...base.assets.find((asset) => asset.id === 'asset-interview')!,
      duration: 10,
      metadata: {
        hasAudio: true,
        mimeType: 'video/mp4',
      },
      mediaCache: {
        generatedAt: '2026-06-13T00:00:00.000Z',
        warnings: [],
        waveformPeaks: [0.05, 0.1, 0.9, 0.2, 0.75, 0.15, 0.6, 0.1, 0.05, 0.04],
      },
    };
    const targetAsset = {
      id: 'asset-external-recorder',
      name: 'external-recorder.wav',
      kind: 'audio' as const,
      source: '/imports/external-recorder.wav',
      renderPath: 'E:/media/external-recorder.wav',
      duration: 13,
      mediaCache: {
        generatedAt: '2026-06-13T00:00:00.000Z',
        warnings: [],
        waveformPeaks: [0.02, 0.03, 0.04, 0.05, 0.1, 0.9, 0.2, 0.75, 0.15, 0.6, 0.1, 0.05, 0.04],
      },
      metadata: {
        mimeType: 'audio/wav',
        hasAudio: true,
      },
    };
    const referenceClip = createClip({
      id: 'clip-sync-reference',
      assetId: referenceAsset.id,
      trackId: 'track-v1',
      name: 'Camera audio',
      kind: 'video',
      start: 20,
      duration: 10,
      sourceIn: 0,
      color: '#60a5fa',
    });
    const targetClip = createClip({
      id: 'clip-sync-target',
      assetId: targetAsset.id,
      trackId: 'track-a-sync',
      name: 'External recorder',
      kind: 'audio',
      start: 5,
      duration: 13,
      sourceIn: 0,
      color: '#84cc16',
    });
    const project = {
      ...base,
      duration: 40,
      assets: [referenceAsset, targetAsset],
      tracks: [
        {
          ...base.tracks.find((track) => track.id === 'track-v1')!,
          clips: [referenceClip],
        },
        {
          id: 'track-a-sync',
          name: 'External sync',
          kind: 'audio' as const,
          muted: false,
          solo: false,
          locked: false,
          clips: [targetClip],
        },
      ],
    };
    const plan = buildWaveformSyncPlan(project, referenceClip.id, targetClip.id, { maxOffsetSeconds: 8 });
    const result = applyWaveformSync(project, referenceClip.id, targetClip.id, { maxOffsetSeconds: 8 });
    const syncedTarget = result.project.tracks.find((track) => track.id === 'track-a-sync')?.clips[0];

    expect(plan).toMatchObject({
      referenceClipId: referenceClip.id,
      targetClipId: targetClip.id,
      lagSeconds: 3,
      requestedDelta: 12,
      appliedDelta: 12,
      targetStart: 17,
    });
    expect(plan.confidence).toBeGreaterThan(0.98);
    expect(plan.warnings).toEqual([]);
    expect(syncedTarget?.start).toBe(17);

    const linkedResult = applyWaveformSyncAndLink(project, referenceClip.id, targetClip.id, { maxOffsetSeconds: 8 });
    const linkedReference = linkedResult.project.tracks.find((track) => track.id === 'track-v1')?.clips[0];
    const linkedTarget = linkedResult.project.tracks.find((track) => track.id === 'track-a-sync')?.clips[0];
    expect(linkedReference?.automationTags).toEqual(expect.arrayContaining([
      'embedded-audio:disabled',
      `detached-audio:${targetClip.id}`,
    ]));
    expect(linkedTarget).toMatchObject({
      start: 17,
      automationTags: expect.arrayContaining([
        'detached-audio',
        `linked-video:${referenceClip.id}`,
      ]),
    });
    expect(expandClipIdsWithLinkedClips(linkedResult.project, [referenceClip.id])).toEqual([referenceClip.id, targetClip.id]);

    const movedLinkedProject = moveClips(
      linkedResult.project,
      expandClipIdsWithLinkedClips(linkedResult.project, [referenceClip.id]),
      2,
    );
    expect(movedLinkedProject.tracks.find((track) => track.id === 'track-v1')?.clips[0].start).toBe(22);
    expect(movedLinkedProject.tracks.find((track) => track.id === 'track-a-sync')?.clips[0].start).toBe(19);
  });

