  it('applies Ken Burns motion presets as editable keyframes with preview and FFmpeg parity', () => {
    const project = createDefaultEditorProject();
    const panProject = applyMotionPreset(project, 'clip-interview-1', 'pan-left');
    const panClip = panProject.tracks[0].clips.find((clip) => clip.id === 'clip-interview-1');
    const positionXKeyframes = panClip?.keyframes.filter((keyframe) => keyframe.property === 'positionX') ?? [];
    const scaleKeyframes = panClip?.keyframes.filter((keyframe) => keyframe.property === 'scale') ?? [];

    expect(positionXKeyframes.map((keyframe) => ({ time: keyframe.time, value: keyframe.value }))).toEqual([
      { time: 0, value: 60 },
      { time: 28, value: -60 },
    ]);
    expect(scaleKeyframes.map((keyframe) => ({ time: keyframe.time, value: keyframe.value }))).toEqual([
      { time: 0, value: 1.12 },
      { time: 28, value: 1.12 },
    ]);
    expect(buildProgramPreviewStack(panProject, 14).primaryLayer?.style).toMatchObject({
      positionX: 0,
      positionY: 0,
      scale: 1.12,
    });

    const panPlan = buildFfmpegRenderPlan(panProject, 'profile-youtube-4k');
    expect(panPlan.filterGraph.some((filter) => (
      filter.includes("scale=w='3840*(") &&
      filter.includes('1.12') &&
      filter.includes(':eval=frame')
    ))).toBe(true);
    expect(panPlan.filterGraph.some((filter) => (
      filter.includes("overlay=x='(W-w)/2+(") &&
      filter.includes('60+(-120)') &&
      filter.includes('eval=frame')
    ))).toBe(true);

    const parity = buildPreviewRenderParityReport(panProject, 'profile-youtube-4k', { sampleTimes: [14] });
    expect(parity.issues.some((issue) => issue.message.includes('Transform keyframes'))).toBe(false);

    const zoomProject = applyMotionPreset(panProject, 'clip-interview-1', 'zoom-in');
    const zoomClip = zoomProject.tracks[0].clips.find((clip) => clip.id === 'clip-interview-1');
    expect(zoomClip?.keyframes.filter((keyframe) => (
      keyframe.property === 'positionX' ||
      keyframe.property === 'positionY' ||
      keyframe.property === 'scale'
    ))).toHaveLength(6);
    expect(zoomClip?.keyframes.filter((keyframe) => keyframe.property === 'positionX').map((keyframe) => keyframe.value)).toEqual([0, 0]);
    expect(zoomClip?.keyframes.filter((keyframe) => keyframe.property === 'scale').map((keyframe) => keyframe.value)).toEqual([1, 1.18]);

    expect(() => applyMotionPreset(project, 'clip-music-1', 'zoom-in')).toThrow('Motion presets are available for visual clips.');

    const batchMotionResult = applyMotionPresetToClips(project, ['clip-interview-1', 'clip-title-1', 'clip-music-1'], 'zoom-out');
    const batchMotionInterview = batchMotionResult.project.tracks[0].clips.find((clip) => clip.id === 'clip-interview-1');
    const batchMotionTitle = batchMotionResult.project.tracks[2].clips.find((clip) => clip.id === 'clip-title-1');
    expect(batchMotionResult.updatedClipIds).toEqual(['clip-interview-1', 'clip-title-1']);
    expect(batchMotionResult.skipped).toEqual([{ clipId: 'clip-music-1', reason: 'Motion presets are available for visual clips.' }]);
    expect(batchMotionInterview?.keyframes.filter((keyframe) => keyframe.property === 'scale').map((keyframe) => keyframe.value)).toEqual([1.18, 1]);
    expect(batchMotionTitle?.keyframes.filter((keyframe) => keyframe.property === 'scale').map((keyframe) => keyframe.value)).toEqual([1.18, 1]);
    expect(() => applyMotionPresetToClips(project, ['clip-music-1'], 'zoom-in')).toThrow('No selected clips could receive motion preset');
    expect(() => applyMotionPresetToClips(project, [], 'zoom-in')).toThrow('No target clips selected.');
    const lockedMotionProject = updateClip(project, 'clip-interview-1', { locked: true });
    expect(() => applyMotionPresetToClips(lockedMotionProject, ['clip-interview-1'], 'zoom-in')).toThrow('Cannot edit motion presets on a locked track or clip.');
  });

