  it('classifies FFmpeg render failures into actionable diagnostics', () => {
    const plan = buildFfmpegRenderPlan(createDefaultEditorProject(), 'profile-youtube-4k');
    const missingFfmpeg = analyzeRenderFailure(plan, '', 'spawn ffmpeg ENOENT');

    expect(missingFfmpeg).toMatchObject({
      category: 'missing-ffmpeg',
      retryable: false,
    });
    expect(missingFfmpeg.actions[0]).toContain('Install FFmpeg');

    const baseProject = createDefaultEditorProject();
    const browserOnlyPlan = buildFfmpegRenderPlan({
      ...baseProject,
      assets: baseProject.assets.map((asset) => (
        asset.id === 'asset-interview'
          ? { ...asset, source: 'blob:http://localhost/interview', renderPath: undefined }
          : asset
      )),
    }, 'profile-youtube-4k');
    const unsupportedSource = analyzeRenderFailure(browserOnlyPlan);
    const unsupportedSourceFromInput = analyzeRenderFailure({
      ...plan,
      warnings: [],
      inputs: [
        {
          ...plan.inputs[0],
          source: 'local://pending-import/interview',
        },
      ],
    });

    expect(unsupportedSource.category).toBe('unsupported-source');
    expect(unsupportedSource.retryable).toBe(false);
    expect(canRetryRenderDiagnostic(unsupportedSource)).toBe(true);
    expect(formatRenderRetryActionLabel(unsupportedSource)).toBe('Retry current export');
    expect(unsupportedSourceFromInput).toMatchObject({
      category: 'unsupported-source',
      retryable: false,
    });
  });

  it('keeps long FFmpeg commands collapsed in the default render readout', () => {
    const commandText = `ffmpeg ${'filter='.repeat(700)} renders/output.mp4`;
    const preview = buildRenderCommandPreview(commandText, 120);

    expect(preview.isTruncated).toBe(true);
    expect(preview.text.length).toBeLessThan(commandText.length);
    expect(preview.text).toMatch(/\.\.\.$/);
    expect(preview.omittedCharacterCount).toBe(commandText.length - 120);

    expect(buildRenderCommandPreview('ffmpeg -i input output', 120)).toEqual({
      text: 'ffmpeg -i input output',
      isTruncated: false,
      omittedCharacterCount: 0,
    });
  });

