  it('supports slip, roll, and slide precision edits', () => {
    const project = createDefaultEditorProject();

    const slippedProject = slipClip(project, 'clip-interview-2', 3);
    const slippedClip = slippedProject.tracks[0].clips.find((clip) => clip.id === 'clip-interview-2');
    expect(slippedClip).toMatchObject({
      start: 32,
      sourceIn: 31,
      duration: 34,
    });

    const rollStartProject = rollTrimClip(project, 'clip-interview-2', 'start', -2);
    const rollStartPrevious = rollStartProject.tracks[0].clips.find((clip) => clip.id === 'clip-interview-1');
    const rollStartClip = rollStartProject.tracks[0].clips.find((clip) => clip.id === 'clip-interview-2');
    expect(rollStartPrevious?.duration).toBe(26);
    expect(rollStartClip).toMatchObject({
      start: 30,
      sourceIn: 26,
      duration: 36,
    });

    const rollEndProject = rollTrimClip(project, 'clip-interview-1', 'end', 2);
    const rollEndClip = rollEndProject.tracks[0].clips.find((clip) => clip.id === 'clip-interview-1');
    const rollEndNext = rollEndProject.tracks[0].clips.find((clip) => clip.id === 'clip-interview-2');
    expect(rollEndClip?.duration).toBe(30);
    expect(rollEndNext).toMatchObject({
      start: 34,
      sourceIn: 30,
      duration: 32,
    });

    const projectWithThirdClip = insertAssetRangeOnTimeline(project, 'asset-interview', {
      start: 70,
      targetTrackId: 'track-v1',
      duration: 10,
    });
    const slidProject = slideClip(projectWithThirdClip, 'clip-interview-2', 2);
    const slidePrevious = slidProject.tracks[0].clips.find((clip) => clip.id === 'clip-interview-1');
    const slideClipItem = slidProject.tracks[0].clips.find((clip) => clip.id === 'clip-interview-2');
    const slideNext = slidProject.tracks[0].clips.find((clip) => (
      clip.assetId === 'asset-interview' && clip.start === 72 && clip.sourceIn === 2
    ));

    expect(slidePrevious?.duration).toBe(30);
    expect(slideClipItem).toMatchObject({
      start: 34,
      sourceIn: 28,
      duration: 34,
    });
    expect(slideNext?.duration).toBe(8);
  });

