  it('groups and ungroups clips as persistent selection units', () => {
    const project = createDefaultEditorProject();
    const groupedProject = groupClips(project, ['clip-interview-1', 'clip-ai-city'], { groupId: 'story-block' });

    const groupedInterview = groupedProject.tracks[0].clips.find((clip) => clip.id === 'clip-interview-1');
    const groupedCity = groupedProject.tracks[1].clips.find((clip) => clip.id === 'clip-ai-city');
    expect(groupedInterview?.automationTags).toContain('clip-group:story-block');
    expect(groupedCity?.automationTags).toContain('clip-group:story-block');
    expect(expandClipIdsWithLinkedAndGroupedClips(groupedProject, ['clip-ai-city'])).toEqual(['clip-interview-1', 'clip-ai-city']);
    expect(findClipIdsAtTime(groupedProject, 4, { trackId: 'track-v1' })).toEqual(['clip-interview-1', 'clip-ai-city']);
    expect(findClipIdsInRange(groupedProject, { start: 19, end: 20 }, { trackId: 'track-v2' })).toEqual(['clip-interview-1', 'clip-ai-city']);
    expect(findClipSelectionRange(groupedProject, ['clip-ai-city'])).toEqual({ start: 0, end: 28 });

    const movedGroupProject = moveClips(
      groupedProject,
      expandClipIdsWithLinkedAndGroupedClips(groupedProject, ['clip-ai-city']),
      4,
      { preventOverlap: true },
    );
    expect(movedGroupProject.tracks[0].clips.find((clip) => clip.id === 'clip-interview-1')?.start).toBe(4);
    expect(movedGroupProject.tracks[1].clips.find((clip) => clip.id === 'clip-ai-city')?.start).toBe(22);

    const mutedGroupProject = toggleClipsState(groupedProject, ['clip-ai-city'], 'muted');
    expect(mutedGroupProject.tracks[0].clips.find((clip) => clip.id === 'clip-interview-1')?.muted).toBe(true);
    expect(mutedGroupProject.tracks[1].clips.find((clip) => clip.id === 'clip-ai-city')?.muted).toBe(true);
    expect(buildProgramPreviewStack(mutedGroupProject, 4).layers.find((layer) => layer.clip.id === 'clip-interview-1')?.visible).toBe(false);

    const unmutedGroupProject = toggleClipsState(mutedGroupProject, ['clip-ai-city'], 'muted');
    expect(unmutedGroupProject.tracks[0].clips.find((clip) => clip.id === 'clip-interview-1')?.muted).toBe(false);
    expect(unmutedGroupProject.tracks[1].clips.find((clip) => clip.id === 'clip-ai-city')?.muted).toBe(false);

    const lockedGroupProject = toggleClipsState(groupedProject, ['clip-ai-city'], 'locked');
    expect(lockedGroupProject.tracks[0].clips.find((clip) => clip.id === 'clip-interview-1')?.locked).toBe(true);
    expect(lockedGroupProject.tracks[1].clips.find((clip) => clip.id === 'clip-ai-city')?.locked).toBe(true);
    expect(() => toggleClipsState(lockedGroupProject, ['clip-ai-city'], 'muted')).toThrow('Cannot update a locked clip.');
    const unlockedGroupProject = toggleClipsState(lockedGroupProject, ['clip-ai-city'], 'locked');
    expect(unlockedGroupProject.tracks[0].clips.find((clip) => clip.id === 'clip-interview-1')?.locked).toBe(false);
    expect(unlockedGroupProject.tracks[1].clips.find((clip) => clip.id === 'clip-ai-city')?.locked).toBe(false);

    const ungroupedProject = ungroupClips(groupedProject, ['clip-ai-city']);
    expect(ungroupedProject.tracks[0].clips.find((clip) => clip.id === 'clip-interview-1')?.automationTags).not.toContain('clip-group:story-block');
    expect(ungroupedProject.tracks[1].clips.find((clip) => clip.id === 'clip-ai-city')?.automationTags).not.toContain('clip-group:story-block');
    expect(findClipIdsAtTime(ungroupedProject, 4, { trackId: 'track-v1' })).toEqual(['clip-interview-1']);
    expect(findClipIdsAtTime(groupedProject, 4, { trackId: 'track-v1', includeGrouped: false })).toEqual(['clip-interview-1']);
    expect(() => groupClips(project, ['clip-interview-1'])).toThrow('Select at least two clips to group.');
    expect(() => ungroupClips(project, ['clip-interview-1'])).toThrow('Selected clips are not grouped.');

    const lockedProject = {
      ...project,
      tracks: project.tracks.map((track) => (
        track.id === 'track-v2'
          ? { ...track, locked: true }
          : track
      )),
    };
    expect(() => groupClips(lockedProject, ['clip-interview-1', 'clip-ai-city'])).toThrow('Cannot group locked tracks or clips.');
  });

