  it('fills local STT speaker embeddings from an external speaker encoder command', async () => {
    const project = createDefaultEditorProject();
    const clip = project.tracks[0].clips.find((item) => item.id === 'clip-interview-1')!;
    const asset = project.assets.find((item) => item.id === 'asset-interview')!;
    const captions = alignSttSegmentsToClip([
      { start: 0, end: 4, text: 'Needs external embedding', confidence: 0.91 },
      { start: 4, end: 8, text: 'Already embedded', confidence: 0.9, speakerEmbedding: [0.88, 0.12] },
    ], clip, { speaker: 'Speaker' });
    const manifest = buildSttSpeakerEncoderManifest({
      inputPath: 'interview.wav',
      clip,
      assetDuration: asset.duration,
      captions,
      language: 'en',
    });

    expect(manifest).toMatchObject({
      version: 1,
      clipId: clip.id,
      language: 'en',
    });
    expect(manifest.captions).toHaveLength(1);
    expect(manifest.captions[0]).toMatchObject({
      id: captions[0].id,
      text: 'Needs external embedding',
      sourceStart: clip.sourceIn,
    });

    const applied = applySttSpeakerEncoderOutput(captions, JSON.stringify({
      embeddings: [
        { captionId: captions[0].id, speakerEmbedding: [0.71, 0.22, 0.11] },
        { captionId: captions[1].id, speakerEmbedding: [0.01, 0.99, 0.2] },
        { captionId: 'caption-missing', speakerEmbedding: ['bad', 0.2] },
      ],
    }));
    expect(applied.generatedCount).toBe(1);
    expect(applied.preservedCount).toBe(1);
    expect(applied.skippedCount).toBe(0);
    expect(applied.captions[0].speakerEmbedding).toEqual([0.71, 0.22, 0.11]);
    expect(applied.captions[1].speakerEmbedding).toEqual([0.88, 0.12]);
    expect(applied.warnings.some((warning) => warning.includes('invalid embedding'))).toBe(true);

    const command = buildSttSpeakerEncoderCommand('encoder --input {input} --manifest {manifest} --language {language} --clip {clipId}', {
      inputPath: 'interview.wav',
      outputDir: 'encoder-out',
      manifestPath: 'encoder-manifest.json',
      language: 'en',
      clipId: clip.id,
    });
    expect(command).toMatchObject({
      command: 'encoder',
      args: ['--input', 'interview.wav', '--manifest', 'encoder-manifest.json', '--language', 'en', '--clip', clip.id],
    });

    const outputDir = await mkdtemp(joinPath(tmpdir(), 'danbi-speaker-encoder-'));
    const inputPath = joinPath(outputDir, 'interview.wav');
    const resourcesPath = joinPath(outputDir, 'resources');
    const presetDir = joinPath(resourcesPath, 'speaker-encoder');
    const previousSttCommand = process.env.DANBI_STT_COMMAND;
    const previousSpeakerEncoderCommand = process.env.DANBI_STT_SPEAKER_ENCODER_COMMAND;
    const previousSpeakerEncoderPresetDir = process.env.DANBI_STT_SPEAKER_ENCODER_PRESET_DIR;
    const previousElectronResourcesPath = process.env.DANBI_ELECTRON_RESOURCES_PATH;
    try {
      await writeFile(inputPath, 'fake audio input');
      await mkdir(presetDir, { recursive: true });
      await writeFile(joinPath(presetDir, 'encoder.js'), [
        "const fs = require('fs');",
        "const manifestPath = process.argv[process.argv.indexOf('--manifest') + 1];",
        "const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));",
        "process.stdout.write(JSON.stringify({ embeddings: manifest.captions.map((caption, index) => ({ captionId: caption.id, speakerEmbedding: [0.61 + index, 0.31, 0.08] })) }));",
      ].join('\n'), 'utf8');
      await writeFile(joinPath(presetDir, 'danbi-speaker-encoder.json'), JSON.stringify({
        version: 1,
        commandTemplate: 'node "{presetDir}/encoder.js" --manifest {manifest}',
      }, null, 2), 'utf8');

      const commandTemplate = 'node -e "const fs=require(\'fs\');const manifest=JSON.parse(fs.readFileSync(process.argv[1],\'utf8\'));process.stdout.write(JSON.stringify({embeddings:manifest.captions.map((caption,index)=>({captionId:caption.id,speakerEmbedding:[0.71+index,0.21,0.08]}))}));" {manifest}';
      expect(resolveSttSpeakerEncoderCommand({
        explicitCommand: commandTemplate,
        env: { ...process.env, DANBI_ELECTRON_RESOURCES_PATH: resourcesPath },
      })).toBe(commandTemplate);
      const resolvedPresetCommand = resolveSttSpeakerEncoderCommand({
        env: { ...process.env, DANBI_ELECTRON_RESOURCES_PATH: resourcesPath },
      });
      expect(resolvedPresetCommand).toContain('encoder.js');
      expect(resolvedPresetCommand).toContain('--manifest {manifest}');

      process.env.DANBI_STT_COMMAND = `node -e "process.stdout.write(JSON.stringify({segments:[{start:0,end:2,text:'Queue external embedding'}]}));"`;
      delete process.env.DANBI_STT_SPEAKER_ENCODER_COMMAND;
      delete process.env.DANBI_STT_SPEAKER_ENCODER_PRESET_DIR;
      process.env.DANBI_ELECTRON_RESOURCES_PATH = resourcesPath;
      const queueProject = {
        ...project,
        assets: project.assets.map((item) => (
          item.id === asset.id
            ? { ...item, renderPath: inputPath }
            : item
        )),
      };
      const queued = createSttJob(queueProject, ['clip-interview-1'], { execute: true, language: 'en' });
      const completed = await waitForSttJob(queued.id);

      expect(completed?.status).toBe('completed');
      expect(completed?.captions[0]).toMatchObject({
        text: 'Queue external embedding',
        speakerEmbedding: [0.61, 0.31, 0.08],
      });
      expect(completed?.warnings.some((warning) => warning.includes('generated 1 speaker embedding from external speaker encoder'))).toBe(true);
      expect(completed?.warnings.some((warning) => warning.includes('from waveform cache'))).toBe(false);
    } finally {
      if (previousSttCommand === undefined) {
        delete process.env.DANBI_STT_COMMAND;
      } else {
        process.env.DANBI_STT_COMMAND = previousSttCommand;
      }
      if (previousSpeakerEncoderCommand === undefined) {
        delete process.env.DANBI_STT_SPEAKER_ENCODER_COMMAND;
      } else {
        process.env.DANBI_STT_SPEAKER_ENCODER_COMMAND = previousSpeakerEncoderCommand;
      }
      if (previousSpeakerEncoderPresetDir === undefined) {
        delete process.env.DANBI_STT_SPEAKER_ENCODER_PRESET_DIR;
      } else {
        process.env.DANBI_STT_SPEAKER_ENCODER_PRESET_DIR = previousSpeakerEncoderPresetDir;
      }
      if (previousElectronResourcesPath === undefined) {
        delete process.env.DANBI_ELECTRON_RESOURCES_PATH;
      } else {
        process.env.DANBI_ELECTRON_RESOURCES_PATH = previousElectronResourcesPath;
      }
      await rm(outputDir, { recursive: true, force: true });
    }
  });

  it('reviews and cleans imported STT captions', () => {
    const project = {
      ...createDefaultEditorProject(),
      captions: [
        {
          id: 'caption-stt-a-1',
          start: 1,
          end: 1.25,
          text: '  hello   ',
          confidence: 0.6,
          speaker: 'Host',
          words: [{ start: 0.9, end: 1.1, text: ' hello ', confidence: 1.2 }],
        },
        {
          id: 'caption-stt-a-2',
          start: 1.3,
          end: 1.8,
          text: 'world',
          confidence: 0.94,
          speaker: 'Host',
        },
        {
          id: 'caption-stt-a-3',
          start: 4,
          end: 4.45,
          text: 'This is a very very very very very dense caption line',
          confidence: 0.95,
        },
        {
          id: 'caption-manual-1',
          start: 8,
          end: 9,
          text: 'Manual caption',
        },
      ],
    };

    const report = buildSttCaptionReview(project, { requireSpeaker: true });
    const issueKinds = report.issues.map((issue) => issue.kind);

    expect(report.captionCount).toBe(3);
    expect(report.wordTimedCaptionCount).toBe(1);
    expect(report.lowConfidenceCount).toBe(1);
    expect(issueKinds).toEqual(expect.arrayContaining([
      'low-confidence',
      'too-short',
      'too-fast',
      'missing-speaker',
      'word-timing-drift',
    ]));

    const cleanup = cleanSttCaptions(project);
    const cleanedCaptions = cleanup.project.captions;
    const merged = cleanedCaptions.find((caption) => caption.id === 'caption-stt-a-1');

    expect(cleanup.mergedCaptionCount).toBe(1);
    expect(cleanup.selectedCaptionIds).toContain('caption-stt-a-1');
    expect(cleanedCaptions.some((caption) => caption.id === 'caption-stt-a-2')).toBe(false);
    expect(merged).toMatchObject({
      text: 'hello world',
      speaker: 'Host',
      confidence: 0.6,
    });
    expect(merged!.end - merged!.start).toBeGreaterThanOrEqual(0.65);
    expect(merged!.words?.[0]).toMatchObject({
      start: 1,
      text: 'hello',
      confidence: 1,
    });
    expect(cleanedCaptions.find((caption) => caption.id === 'caption-manual-1')?.text).toBe('Manual caption');
  });

  it('flags and repairs overlapping STT word timings inside caption ranges', () => {
    const project = {
      ...createDefaultEditorProject(),
      captions: [
        {
          id: 'caption-stt-word-drift',
          start: 10,
          end: 12,
          text: 'first second third',
          confidence: 0.95,
          words: [
            { start: 10.6, end: 10.9, text: 'second' },
            { start: 10.2, end: 10.7, text: 'first' },
            { start: 10.65, end: 11.1, text: 'third' },
          ],
        },
      ],
    };

    const report = buildSttCaptionReview(project);
    expect(report.issues).toEqual(expect.arrayContaining([
      expect.objectContaining({
        captionId: 'caption-stt-word-drift',
        kind: 'word-timing-drift',
        message: 'Word timing is outside the caption range or overlaps',
      }),
    ]));

    const cleaned = cleanSttCaptions(project);
    const words = cleaned.project.captions.find((caption) => caption.id === 'caption-stt-word-drift')?.words ?? [];

    expect(cleaned.changedCaptionCount).toBe(1);
    expect(words.map((word) => word.text)).toEqual(['first', 'second', 'third']);
    expect(words.map((word) => [word.start, word.end])).toEqual([
      [10.2, 10.7],
      [10.7, 10.9],
      [10.9, 11.1],
    ]);
  });

  it('builds STT speaker diarization timelines and applies draft speaker labels', () => {
    const project = {
      ...createDefaultEditorProject(),
      captions: [
        {
          id: 'caption-stt-speaker-1',
          start: 0,
          end: 1,
          text: 'Welcome back',
          confidence: 0.95,
          speaker: 'Host',
        },
        {
          id: 'caption-stt-speaker-2',
          start: 1.15,
          end: 2,
          text: 'Today we test the editor',
          confidence: 0.9,
        },
        {
          id: 'caption-stt-speaker-3',
          start: 5.2,
          end: 6,
          text: 'I have a question',
          confidence: 0.86,
        },
        {
          id: 'caption-stt-speaker-4',
          start: 6.1,
          end: 7,
          text: 'Can it label speakers',
          confidence: 0.84,
        },
        {
          id: 'caption-stt-speaker-5',
          start: 8,
          end: 9,
          text: 'Yes it can',
          confidence: 0.91,
          speaker: 'Host',
        },
        {
          id: 'caption-manual-speaker-note',
          start: 12,
          end: 13,
          text: 'Manual note',
        },
      ],
    };

    const report = buildSpeakerDiarizationReport(project);
    expect(report.captionCount).toBe(5);
    expect(report.missingSpeakerCount).toBe(3);
    expect(report.changedCaptionIds).toEqual([
      'caption-stt-speaker-2',
      'caption-stt-speaker-3',
      'caption-stt-speaker-4',
    ]);
    expect(report.assignments['caption-stt-speaker-2']).toBe('Host');
    expect(report.assignments['caption-stt-speaker-3']).toBe('Speaker 1');
    expect(report.assignments['caption-stt-speaker-4']).toBe('Speaker 1');
    expect(report.speakers.map((speaker) => speaker.label)).toEqual(['Host', 'Speaker 1']);
    expect(report.turns.map((turn) => ({ speaker: turn.speaker, captionCount: turn.captionCount }))).toEqual([
      { speaker: 'Host', captionCount: 2 },
      { speaker: 'Speaker 1', captionCount: 2 },
      { speaker: 'Host', captionCount: 1 },
    ]);

    const applied = applySpeakerDiarization(project);
    const captions = applied.project.captions;
    expect(applied.changedCaptionIds).toEqual(report.changedCaptionIds);
    expect(captions.find((caption) => caption.id === 'caption-stt-speaker-2')?.speaker).toBe('Host');
    expect(captions.find((caption) => caption.id === 'caption-stt-speaker-3')?.speaker).toBe('Speaker 1');
    expect(captions.find((caption) => caption.id === 'caption-manual-speaker-note')?.speaker).toBeUndefined();

    const selectedOnly = applySpeakerDiarization(project, {
      targetCaptionIds: ['caption-manual-speaker-note'],
      includeNonStt: true,
    });
    expect(selectedOnly.project.captions.find((caption) => caption.id === 'caption-manual-speaker-note')?.speaker).toBe('Speaker 1');
    expect(applySpeakerDiarization(applied.project).changedCaptionIds).toEqual([]);
  });

