    expect(report.assignmentSources['caption-stt-embed-host-return']).toBe('embedding');
    expect(report.assignments['caption-stt-embed-guest-return']).toBe('Speaker 1');
    expect(report.assignmentSources['caption-stt-embed-guest-return']).toBe('embedding');
    expect(report.speakers.find((speaker) => speaker.label === 'Host')?.embeddingCaptionCount).toBe(2);
    expect(report.warnings).toEqual(expect.arrayContaining([
      '1 speaker embedding was ignored because it was invalid or too short.',
    ]));
    expect(applied.project.captions.find((caption) => caption.id === 'caption-stt-embed-host-return')?.speaker).toBe('Host');
    expect(applied.project.captions.find((caption) => caption.id === 'caption-stt-embed-guest-return')?.speaker).toBe('Speaker 1');
