  it('flags ambiguous and low-similarity speaker embeddings for diarization review', () => {
    const project = {
      ...createDefaultEditorProject(),
      captions: [
        {
          id: 'caption-stt-margin-host',
          start: 0,
          end: 1,
          text: 'Host voice model',
          confidence: 0.96,
          speaker: 'Host',
          speakerEmbedding: [1, 0, 0],
        },
        {
          id: 'caption-stt-margin-guest',
          start: 4,
          end: 5,
          text: 'Guest voice model',
          confidence: 0.93,
          speaker: 'Guest',
          speakerEmbedding: [0, 1, 0],
        },
        {
          id: 'caption-stt-margin-ambiguous',
          start: 20,
          end: 21,
          text: 'This is too close to both known speakers',
          confidence: 0.88,
          speakerEmbedding: [0.72, 0.69, 0],
        },
        {
          id: 'caption-stt-margin-low',
          start: 25,
          end: 26,
          text: 'This embedding does not match known voices',
          confidence: 0.84,
          speakerEmbedding: [0, 0, 1],
        },
      ],
    };

    const report = buildSpeakerDiarizationReport(project, {
      speakerEmbeddingSimilarityThreshold: 0.6,
      speakerEmbeddingSimilarityMargin: 0.08,
      maxSameSpeakerGap: 0.5,
      carryKnownSpeakerGap: 0.5,
    });

    expect(report.embeddingCaptionCount).toBe(4);
    expect(report.embeddingAssignedCaptionCount).toBe(0);
    expect(report.embeddingAmbiguousCaptionCount).toBe(1);
    expect(report.embeddingLowSimilarityCaptionCount).toBe(1);
    expect(report.assignmentSources['caption-stt-margin-ambiguous']).toBe('inferred');
    expect(report.assignmentSources['caption-stt-margin-low']).toBe('inferred');
    expect(report.assignments['caption-stt-margin-ambiguous']).not.toBe('Host');
    expect(report.assignments['caption-stt-margin-low']).not.toBe('Host');
    expect(report.reviewCaptionIds).toEqual(expect.arrayContaining([
      'caption-stt-margin-ambiguous',
      'caption-stt-margin-low',
    ]));
    expect(report.warnings).toEqual(expect.arrayContaining([
      '1 speaker embedding match was ambiguous and should be reviewed.',
      '1 speaker embedding match was below the similarity threshold and used fallback labeling.',
    ]));
  });

