    const objectMaskClip = objectMaskResult.project.tracks[0].clips.find((clip) => clip.id === 'clip-interview-2');
    const objectMaskAsset = objectMaskResult.project.assets.find((asset) => asset.id === objectMaskClip?.assetId);
