  it('executes allowed editor webhooks and blocks unlisted external targets', async () => {
    const project = {
      ...createDefaultEditorProject(),
      automation: [
        {
          id: 'rule-webhook-local',
          name: 'Notify local pipeline',
          provider: 'webhook' as const,
          trigger: 'manual' as const,
          targetTrackIds: ['track-v2'],
          parameters: {
            url: 'http://localhost:9000/hooks/editor',
            token: 'local-dev',
          },
        },
        {
          id: 'rule-webhook-public',
          name: 'Notify public pipeline',
          provider: 'webhook' as const,
          trigger: 'manual' as const,
          targetTrackIds: ['track-v2'],
          parameters: {
            url: 'https://automation.example.com/hooks/editor',
          },
        },
      ] as EditorProject['automation'],
    };
    const plan = buildEditorHookPlan(project, { event: 'manual', selectedClipIds: ['clip-ai-city'] });
    const calls: Array<{ input: string | URL; init?: RequestInit }> = [];
    const fetchImpl = async (input: string | URL, init?: RequestInit) => {
      calls.push({ input, init });
      return new Response('accepted', { status: 202 });
    };

    const result = await executeEditorWebhookPayloads(plan, {
      allowLocalhost: true,
      fetchImpl,
      timeoutMs: 1000,
    });

    expect(result.requestedCount).toBe(2);
    expect(result.sentCount).toBe(1);
    expect(result.skippedCount).toBe(1);
    expect(result.failedCount).toBe(0);
    expect(calls).toHaveLength(1);
    expect(String(calls[0].input)).toBe('http://localhost:9000/hooks/editor');
    expect((calls[0].init?.headers as Record<string, string>).Authorization).toBe('Bearer local-dev');
    expect(String(calls[0].init?.body)).toContain('"token":"[redacted]"');
    expect(String(calls[0].init?.body)).not.toContain('local-dev');
    expect(result.results.find((item) => item.targetUrl?.includes('automation.example.com'))?.status).toBe('skipped');

    const publicResult = await executeEditorWebhookPayloads(plan, {
      allowedUrls: ['automation.example.com'],
      fetchImpl,
      timeoutMs: 1000,
    });
    expect(publicResult.results.find((item) => item.targetUrl?.includes('automation.example.com'))?.status).toBe('sent');
  });

  it('resolves webhook bearer tokens from scoped environment secrets without storing the secret in the payload', async () => {
    const project = {
      ...createDefaultEditorProject(),
      automation: [
        {
          id: 'rule-webhook-secret',
          name: 'Notify secret pipeline',
          provider: 'webhook' as const,
          trigger: 'manual' as const,
          targetTrackIds: ['track-v2'],
          parameters: {
            url: 'http://localhost:9000/hooks/editor',
            tokenSecret: 'LOCAL_N8N',
          },
        },
      ] as EditorProject['automation'],
    };
    const plan = buildEditorHookPlan(project, { event: 'manual', selectedClipIds: ['clip-ai-city'] });
    const calls: Array<{ input: string | URL; init?: RequestInit }> = [];
    const fetchImpl = async (input: string | URL, init?: RequestInit) => {
      calls.push({ input, init });
      return new Response('accepted', { status: 202 });
    };

    const result = await executeEditorWebhookPayloads(plan, {
      allowLocalhost: true,
      fetchImpl,
      secretEnv: {
        DANBI_EDITOR_WEBHOOK_SECRET_LOCAL_N8N: 'secret-token',
      },
    });

    expect(result.sentCount).toBe(1);
    expect(calls).toHaveLength(1);
    expect((calls[0].init?.headers as Record<string, string>).Authorization).toBe('Bearer secret-token');
    expect(String(calls[0].init?.body)).toContain('"tokenSecret":"[redacted]"');
    expect(String(calls[0].init?.body)).not.toContain('secret-token');

    const missingSecret = await executeEditorWebhookPayloads(plan, {
      allowLocalhost: true,
      fetchImpl,
      secretEnv: {},
    });
    expect(missingSecret.sentCount).toBe(0);
    expect(missingSecret.skippedCount).toBe(1);
    expect(missingSecret.warnings[0]).toContain('DANBI_EDITOR_WEBHOOK_SECRET_LOCAL_N8N');
  });

  it('retries transient webhook failures without retrying ordinary client errors', async () => {
    const project = {
      ...createDefaultEditorProject(),
      automation: [
        {
          id: 'rule-webhook-retry',
          name: 'Retry pipeline',
          provider: 'webhook' as const,
          trigger: 'manual' as const,
          targetTrackIds: ['track-v2'],
          parameters: {
            url: 'http://localhost:9000/hooks/editor',
          },
        },
      ] as EditorProject['automation'],
    };
    const plan = buildEditorHookPlan(project, { event: 'manual', selectedClipIds: ['clip-ai-city'] });
    let attempt = 0;
    const fetchImpl = async () => {
      attempt += 1;
      return attempt === 1
        ? new Response('busy', { status: 503 })
        : new Response('accepted', { status: 202 });
    };

    const retried = await executeEditorWebhookPayloads(plan, {
      allowLocalhost: true,
      fetchImpl,
      retryCount: 1,
      retryDelayMs: 0,
    });

    expect(retried.sentCount).toBe(1);
    expect(retried.results[0].attemptCount).toBe(2);
    expect(retried.warnings[0]).toContain('attempt 1 failed');

    let clientErrorAttempts = 0;
    const clientError = await executeEditorWebhookPayloads(plan, {
      allowLocalhost: true,
      retryCount: 2,
      retryDelayMs: 0,
      fetchImpl: async () => {
        clientErrorAttempts += 1;
        return new Response('bad request', { status: 400 });
      },
    });

    expect(clientError.failedCount).toBe(1);
    expect(clientErrorAttempts).toBe(1);
    expect(clientError.results[0].attemptCount).toBe(1);
  });

  it('aborts editor webhook execution during retry waits', async () => {
    const project = {
      ...createDefaultEditorProject(),
      automation: [
        {
          id: 'rule-webhook-abort',
          name: 'Abortable retry pipeline',
          provider: 'webhook' as const,
          trigger: 'manual' as const,
          targetTrackIds: ['track-v2'],
          parameters: {
            url: 'http://localhost:9000/hooks/editor',
          },
        },
      ] as EditorProject['automation'],
    };
    const plan = buildEditorHookPlan(project, { event: 'manual', selectedClipIds: ['clip-ai-city'] });
    const controller = new AbortController();
    const calls: Array<{ input: string | URL; init?: RequestInit }> = [];

    const result = await executeEditorWebhookPayloads(plan, {
      allowLocalhost: true,
      retryCount: 1,
      retryDelayMs: 25,
      signal: controller.signal,
      fetchImpl: async (input, init) => {
        calls.push({ input, init });
        return new Response('temporary outage', { status: 503 });
      },
      sleepImpl: async (_durationMs, signal) => {
        expect(signal).toBe(controller.signal);
        controller.abort();
        throw new Error('Webhook execution aborted.');
      },
    });

    expect(calls).toHaveLength(1);
    expect(result.failedCount).toBe(1);
    expect(result.results[0]).toMatchObject({
      status: 'failed',
      attemptCount: 1,
      httpStatus: 503,
      error: 'Webhook execution aborted.',
    });
    expect(result.warnings[0]).toContain('attempt 1 failed');
  });

