  it('adds, updates, and deletes editable captions', () => {
    const withCaption = addCaption(createDefaultEditorProject(), 3, 'Hello');
    const caption = withCaption.captions.find((item) => item.text === 'Hello');

    expect(caption).toBeDefined();

    const updated = updateCaption(withCaption, caption!.id, {
      start: 4,
      end: 6,
      text: 'Edited caption',
      speaker: 'Host',
    });
    const editedCaption = updated.captions.find((item) => item.id === caption!.id);

    expect(editedCaption?.start).toBe(4);
    expect(editedCaption?.end).toBe(6);
    expect(editedCaption?.text).toBe('Edited caption');
    expect(editedCaption?.speaker).toBe('Host');

    const styled = updateCaption(updated, caption!.id, {
      style: {
        fontSize: 72,
        fontColor: '#ffee99',
        boxEnabled: false,
        position: 'middle',
        align: 'right',
      },
    });
    const styledCaption = styled.captions.find((item) => item.id === caption!.id);
    expect(styledCaption?.style).toMatchObject({
      fontSize: 72,
      fontColor: '#ffee99',
      boxEnabled: false,
      position: 'middle',
      align: 'right',
    });
    expect(buildProgramPreviewStack(styled, 4.2).activeCaptions.some((item) => item.id === caption!.id)).toBe(true);

    const withSecondCaption = addCaption(styled, 7, 'Second caption');
    const secondCaption = withSecondCaption.captions.find((item) => item.text === 'Second caption');
    const batchStyled = updateCaptionsStyle(withSecondCaption, [caption!.id, secondCaption!.id], {
      fontSize: 64,
      fontColor: '#00ffcc',
      boxColor: '#111111',
      position: 'bottom',
      align: 'center',
    });
    expect(batchStyled.captions.find((item) => item.id === caption!.id)?.style).toMatchObject({
      fontSize: 64,
      fontColor: '#00ffcc',
      boxColor: '#111111',
      position: 'bottom',
      align: 'center',
    });
    expect(batchStyled.captions.find((item) => item.id === secondCaption!.id)?.style).toMatchObject({
      fontSize: 64,
      fontColor: '#00ffcc',
      boxColor: '#111111',
      position: 'bottom',
      align: 'center',
    });
    expect(updateCaptionsStyle(batchStyled, [caption!.id, secondCaption!.id], { fontSize: 64 })).toBe(batchStyled);
    expect(() => updateCaptionsStyle(batchStyled, [], { fontSize: 64 })).toThrow('Select at least one caption.');
    expect(() => updateCaptionsStyle(batchStyled, ['missing-caption'], { fontSize: 64 })).toThrow('Caption not found.');

    const speakerUpdated = updateCaptionsSpeaker(batchStyled, [caption!.id, secondCaption!.id], 'Narrator');
    expect(speakerUpdated.captions.find((item) => item.id === caption!.id)?.speaker).toBe('Narrator');
    expect(speakerUpdated.captions.find((item) => item.id === secondCaption!.id)?.speaker).toBe('Narrator');
    expect(updateCaptionsSpeaker(speakerUpdated, [caption!.id, secondCaption!.id], 'Narrator')).toBe(speakerUpdated);
    const speakerCleared = updateCaptionsSpeaker(speakerUpdated, [caption!.id, secondCaption!.id], '   ');
    expect(speakerCleared.captions.find((item) => item.id === caption!.id)?.speaker).toBeUndefined();
    expect(() => updateCaptionsSpeaker(batchStyled, [], 'Narrator')).toThrow('Select at least one caption.');
    expect(() => updateCaptionsSpeaker(batchStyled, ['missing-caption'], 'Narrator')).toThrow('Caption not found.');

    const batchDeleted = deleteCaptions(speakerCleared, [caption!.id, secondCaption!.id]);
    expect(batchDeleted.captions.some((item) => item.id === caption!.id || item.id === secondCaption!.id)).toBe(false);
    expect(() => deleteCaptions(batchStyled, [])).toThrow('Select at least one caption.');
    expect(() => deleteCaptions(batchStyled, ['missing-caption'])).toThrow('Caption not found.');

    const reclamped = updateCaption(styled, caption!.id, { start: 10 });
    const reclampedCaption = reclamped.captions.find((item) => item.id === caption!.id);
    expect(reclampedCaption?.end).toBeGreaterThan(reclampedCaption?.start ?? 0);

    const deleted = deleteCaption(reclamped, caption!.id);
    expect(deleted.captions.some((item) => item.id === caption!.id)).toBe(false);
  });

