  it('releases microphone tracks when voiceover startup fails', async () => {
    const previousNavigator = Object.getOwnPropertyDescriptor(globalThis, 'navigator');
    const previousMediaRecorder = Object.getOwnPropertyDescriptor(globalThis, 'MediaRecorder');
    const restoreGlobal = (name: 'navigator' | 'MediaRecorder', descriptor: PropertyDescriptor | undefined) => {
      if (descriptor) {
        Object.defineProperty(globalThis, name, descriptor);
        return;
      }

      Reflect.deleteProperty(globalThis, name);
    };
    const installVoiceoverGlobals = (stream: MediaStream, MediaRecorderCtor: unknown) => {
      Object.defineProperty(globalThis, 'navigator', {
        configurable: true,
        value: {
          mediaDevices: {
            getUserMedia: async () => stream,
          },
        },
      });
      Object.defineProperty(globalThis, 'MediaRecorder', {
        configurable: true,
        value: MediaRecorderCtor,
      });
    };

    try {
      let constructorFailureStopCount = 0;
      const constructorFailureStream = {
        getTracks: () => [{
          stop: () => {
            constructorFailureStopCount += 1;
          },
        }],
      } as unknown as MediaStream;
      class ConstructorFailingMediaRecorder {
        static isTypeSupported() {
          return true;
        }

        constructor() {
          throw new Error('recorder backend unavailable');
        }
      }
      installVoiceoverGlobals(constructorFailureStream, ConstructorFailingMediaRecorder);

      await expect(startVoiceoverRecording({ mimeType: 'audio/webm' })).rejects.toThrow('recorder backend unavailable');
      expect(constructorFailureStopCount).toBe(1);

      let startFailureStopCount = 0;
      const startFailureStream = {
        getTracks: () => [{
          stop: () => {
            startFailureStopCount += 1;
          },
        }],
      } as unknown as MediaStream;
      class StartFailingMediaRecorder {
        static isTypeSupported() {
          return true;
        }

        mimeType = 'audio/webm';

        addEventListener() {
          return undefined;
        }

        start() {
          throw new Error('recorder start failed');
        }
      }
      installVoiceoverGlobals(startFailureStream, StartFailingMediaRecorder);

      await expect(startVoiceoverRecording({ mimeType: 'audio/webm' })).rejects.toThrow('recorder start failed');
      expect(startFailureStopCount).toBe(1);
    } finally {
      restoreGlobal('navigator', previousNavigator);
      restoreGlobal('MediaRecorder', previousMediaRecorder);
    }
  });

  it('times out voiceover recorder stop without leaving microphone tracks open', async () => {
    let stopCalled = false;
    let requestDataCalled = false;
    let listenerRemoved = false;
    const recorder = {
      state: 'recording',
      mimeType: 'audio/webm',
      addEventListener: () => undefined,
      removeEventListener: (type: string) => {
        listenerRemoved = type === 'stop' || listenerRemoved;
      },
      requestData: () => {
        requestDataCalled = true;
      },
      stop: () => undefined,
    } as unknown as MediaRecorder;
    const stream = {
      getTracks: () => [{
        stop: () => {
          stopCalled = true;
        },
      }],
    } as unknown as MediaStream;
    const blob = await stopVoiceoverRecording({
      recorder,
      stream,
      chunks: [new Blob(['voiceover'], { type: 'audio/webm' })],
      startedAtMs: Date.now(),
      mimeType: 'audio/webm',
    }, { stopTimeoutMs: 1 });

    expect(blob.size).toBeGreaterThan(0);
    expect(blob.type).toBe('audio/webm');
    expect(requestDataCalled).toBe(true);
    expect(stopCalled).toBe(true);
    expect(listenerRemoved).toBe(true);
  });

  it('cancels voiceover recording without throwing when recorder stop fails', () => {
    let stoppedTrackCount = 0;
    const recorder = {
      state: 'recording',
      stop: () => {
        throw new Error('recorder backend already closed');
      },
    } as unknown as MediaRecorder;
    const stream = {
      getTracks: () => [
        {
          stop: () => {
            stoppedTrackCount += 1;
          },
        },
        {
          stop: () => {
            stoppedTrackCount += 1;
            throw new Error('device stop failed');
          },
        },
      ],
    } as unknown as MediaStream;

    expect(() => cancelVoiceoverRecording({
      recorder,
      stream,
      chunks: [],
      startedAtMs: Date.now(),
      mimeType: 'audio/webm',
    })).not.toThrow();
    expect(stoppedTrackCount).toBe(2);
  });

