    expect(aiJCutAudio).toMatchObject({ kind: 'ai', start: 9.5, sourceIn: 0.5, duration: 3.5 });
    expect(aiJCutAudio?.automationTags).toEqual(expect.arrayContaining([`linked-video:${aiVideoClip.id}`]));
