    expect(state.selectedSourceRange).toEqual({ in: 0, out: 4.25 });
    expect(state.selectedSourceDuration).toBe(4.25);
    expect(state.selectedSourceAssetBin).toBe('A-roll');
    expect(state.selectedSourcePrimaryKind).toBe('video');
    expect(state.selectedSourceHasPrimaryPatch).toBe(true);
    expect(state.selectedSourceHasAudioPatch).toBe(true);
    expect(state.activeSourcePrimaryPatchTrackId).toBe('track-v2');
    expect(state.activeSourceAudioPatchTrackId).toBe('track-a1');
    expect(state.activeSourcePrimaryPatchTrack?.name).toBe('AI B-roll');
