    expect(relinkedWithoutAnalysisAsset?.metadata?.originalName).toBeUndefined();
    expect(relinkedWithoutAnalysisAsset?.metadata?.importedFileName).toBeUndefined();
    expect(relinkedWithoutAnalysisAsset?.metadata?.originalPath).toBeUndefined();
    expect(relinkedWithoutAnalysisAsset?.metadata?.cacheJobId).toBeUndefined();
    expect(relinkedWithoutAnalysisAsset?.metadata?.displayWidth).toBeUndefined();
    expect(relinkedWithoutAnalysisAsset?.metadata?.displayHeight).toBeUndefined();
