  it('builds normalized waveform peaks from PCM audio cache data', () => {
    const pcm = Buffer.alloc(8);
    pcm.writeInt16LE(0, 0);
    pcm.writeInt16LE(8192, 2);
    pcm.writeInt16LE(-16384, 4);
    pcm.writeInt16LE(32767, 6);

    const peaks = buildAudioPeaksFromPcm(pcm, 4);

    expect(peaks).toEqual([0, 0.25, 0.5, 1]);
  });

  it('detects and ripple-removes silence from waveform peaks', () => {
    const baseProject = createDefaultEditorProject();
    const project = {
      ...baseProject,
      assets: baseProject.assets.map((asset) => (
        asset.id === 'asset-bgm'
          ? {
            ...asset,
            duration: 10,
            mediaCache: {
              generatedAt: '2026-06-12T00:00:00.000Z',
              waveformPeaks: [0.8, 0, 0, 0.7, 0, 0, 0, 0.6, 0.6, 0.6],
              warnings: [],
            },
          }
          : asset
      )),
      tracks: baseProject.tracks.map((track) => (
        track.id === 'track-a1'
          ? {
            ...track,
            clips: track.clips.map((clip) => (
              clip.id === 'clip-music-1'
                ? { ...clip, duration: 10 }
                : clip
            )),
          }
          : track
      )),
    };

    const plan = buildSilenceRemovalPlan(project, 'clip-music-1', {
      threshold: 0.05,
      minSilenceDuration: 1.5,
      padding: 0,
    });

    expect(plan.ranges).toEqual([
      { start: 1, end: 3, duration: 2, sourceStart: 1, sourceEnd: 3 },
      { start: 4, end: 7, duration: 3, sourceStart: 4, sourceEnd: 7 },
    ]);
    expect(plan.removedDuration).toBe(5);

    const result = removeDetectedSilence(project, 'clip-music-1', {
      threshold: 0.05,
      minSilenceDuration: 1.5,
      padding: 0,
      ripple: true,
    });
    const audioClips = result.project.tracks.find((track) => track.id === 'track-a1')?.clips ?? [];

    expect(audioClips.map((clip) => ({
      start: clip.start,
      duration: clip.duration,
      sourceIn: clip.sourceIn,
    }))).toEqual([
      { start: 0, duration: 1, sourceIn: 0 },
      { start: 1, duration: 1, sourceIn: 3 },
      { start: 2, duration: 3, sourceIn: 7 },
    ]);
  });

  it('removes silence from a linked detached audio clip without cutting an overlapping music bed', () => {
    const detachedProject = detachEmbeddedAudio(createDefaultEditorProject(), 'clip-interview-1');
    const detachedAudioClip = detachedProject.tracks
      .flatMap((track) => track.clips)
      .find((clip) => clip.kind === 'audio' && clip.automationTags.includes('linked-video:clip-interview-1'));

    expect(detachedAudioClip).toBeDefined();

    const project = {
      ...detachedProject,
      assets: detachedProject.assets.map((asset) => (
        asset.id === 'asset-interview'
          ? {
            ...asset,
            duration: 28,
            mediaCache: {
              generatedAt: '2026-06-12T00:00:00.000Z',
              waveformPeaks: [0.6, 0.55, 0, 0, 0.7, 0.65, 0.5, 0.55, 0.6, 0.58, 0.6, 0.55, 0.52, 0.5],
              warnings: [],
            },
          }
          : asset
      )),
    };

    const result = removeDetectedSilence(project, detachedAudioClip!.id, {
      threshold: 0.05,
      minSilenceDuration: 3,
      padding: 0,
      ripple: true,
    });
    const musicBed = result.project.tracks
      .find((track) => track.id === 'track-a1')
      ?.clips.find((clip) => clip.id === 'clip-music-1');
    const videoPieces = result.project.tracks
      .find((track) => track.id === 'track-v1')!
      .clips
      .filter((clip) => clip.id === 'clip-interview-1' || clip.id.startsWith('clip-interview-1-split-'))
      .sort((a, b) => a.start - b.start);
    const audioPieces = result.project.tracks
      .flatMap((track) => track.clips)
      .filter((clip) => clip.id === detachedAudioClip!.id || clip.id.startsWith(`${detachedAudioClip!.id}-split-`))
      .sort((a, b) => a.start - b.start);

    expect(result.plan.ranges).toEqual([
      { start: 4, end: 8, duration: 4, sourceStart: 4, sourceEnd: 8 },
    ]);
    expect(musicBed).toMatchObject({ start: 0, duration: 92, sourceIn: 0 });
    expect(videoPieces.map((clip) => ({
      start: clip.start,
      duration: clip.duration,
      sourceIn: clip.sourceIn,
    }))).toEqual([
      { start: 0, duration: 4, sourceIn: 0 },
      { start: 4, duration: 20, sourceIn: 8 },
    ]);
    expect(audioPieces.map((clip) => ({
      start: clip.start,
      duration: clip.duration,
      sourceIn: clip.sourceIn,
    }))).toEqual([
      { start: 0, duration: 4, sourceIn: 0 },
      { start: 4, duration: 20, sourceIn: 8 },
    ]);
    expect(result.project.tracks.find((track) => track.id === 'track-v1')?.clips.find((clip) => clip.id === 'clip-interview-2')?.start).toBe(28);

    videoPieces.forEach((videoPiece, index) => {
      const audioPiece = audioPieces[index];
      expect(videoPiece.automationTags).toContain(`detached-audio:${audioPiece.id}`);
      expect(audioPiece.automationTags).toContain(`linked-video:${videoPiece.id}`);
    });
  });

