  it('parses ffprobe media analysis for durable import metadata', () => {
    const analysis = parseFfprobeOutput(JSON.stringify({
      streams: [
        {
          codec_type: 'video',
          codec_name: 'h264',
          width: 3840,
          height: 2160,
          avg_frame_rate: '30000/1001',
          duration: '8.341',
        },
        {
          codec_type: 'audio',
          codec_name: 'aac',
          channels: 2,
          sample_rate: '48000',
          duration: '8.341',
        },
      ],
      format: {
        duration: '8.341',
        bit_rate: '42000000',
      },
    }), 'video/mp4');

    expect(analysis.duration).toBe(8.341);
    expect(analysis.width).toBe(3840);
    expect(analysis.height).toBe(2160);
    expect(analysis.codedWidth).toBe(3840);
    expect(analysis.codedHeight).toBe(2160);
    expect(analysis.fps).toBe(29.97);
    expect(analysis.videoCodec).toBe('h264');
    expect(analysis.audioCodec).toBe('aac');
    expect(analysis.hasVideo).toBe(true);
    expect(analysis.hasAudio).toBe(true);

    const rotatedAnalysis = parseFfprobeOutput(JSON.stringify({
      streams: [
        {
          codec_type: 'video',
          codec_name: 'h264',
          width: 1920,
          height: 1080,
          avg_frame_rate: '24/1',
          side_data_list: [{ rotation: 90 }],
        },
      ],
      format: { duration: '4.2' },
    }), 'video/mp4');
    expect(rotatedAnalysis.width).toBe(1080);
    expect(rotatedAnalysis.height).toBe(1920);
    expect(rotatedAnalysis.codedWidth).toBe(1920);
    expect(rotatedAnalysis.codedHeight).toBe(1080);
    expect(rotatedAnalysis.rotation).toBe(90);

    const matrixRotatedAnalysis = parseFfprobeOutput(JSON.stringify({
      streams: [
        {
          codec_type: 'video',
          codec_name: 'h264',
          width: 1920,
          height: 1080,
          side_data_list: [{
            displaymatrix: '\n00000000:            0       65536           0\n00000001:       -65536           0           0\n00000002:            0           0  1073741824\n',
          }],
        },
      ],
    }), 'video/mp4');
    expect(matrixRotatedAnalysis.width).toBe(1080);
    expect(matrixRotatedAnalysis.height).toBe(1920);
    expect(matrixRotatedAnalysis.rotation).toBe(270);

    const taggedRotationAnalysis = parseFfprobeOutput(JSON.stringify({
      streams: [
        {
          codec_type: 'video',
          width: 640,
          height: 360,
          tags: { rotate: '-180' },
        },
      ],
    }), 'video/mp4');
    expect(taggedRotationAnalysis.width).toBe(640);
    expect(taggedRotationAnalysis.height).toBe(360);
    expect(taggedRotationAnalysis.rotation).toBe(180);

    const anamorphicAnalysis = parseFfprobeOutput(JSON.stringify({
      streams: [
        {
          codec_type: 'video',
          width: 160,
          height: 180,
          sample_aspect_ratio: '2:1',
          display_aspect_ratio: '16:9',
        },
      ],
      format: { duration: '1.0' },
    }), 'video/mp4');
    expect(anamorphicAnalysis.width).toBe(320);
    expect(anamorphicAnalysis.height).toBe(180);
    expect(anamorphicAnalysis.codedWidth).toBe(160);
    expect(anamorphicAnalysis.codedHeight).toBe(180);
    expect(anamorphicAnalysis.sampleAspectRatio).toBe('2:1');
    expect(anamorphicAnalysis.displayAspectRatio).toBe('16:9');
    expect(anamorphicAnalysis.pixelAspectRatio).toBe(2);

    const rotatedAnamorphicAnalysis = parseFfprobeOutput(JSON.stringify({
      streams: [
        {
          codec_type: 'video',
          width: 160,
          height: 180,
          sample_aspect_ratio: '2:1',
          side_data_list: [{ rotation: 90 }],
        },
      ],
    }), 'video/mp4');
    expect(rotatedAnamorphicAnalysis.width).toBe(180);
    expect(rotatedAnamorphicAnalysis.height).toBe(320);
    expect(rotatedAnamorphicAnalysis.rotation).toBe(90);

    const exifOrientedJpeg = Buffer.from([
      0xff, 0xd8,
      0xff, 0xe1, 0x00, 0x22,
      0x45, 0x78, 0x69, 0x66, 0x00, 0x00,
      0x49, 0x49, 0x2a, 0x00, 0x08, 0x00, 0x00, 0x00,
      0x01, 0x00,
      0x12, 0x01, 0x03, 0x00, 0x01, 0x00, 0x00, 0x00, 0x06, 0x00, 0x00, 0x00,
      0x00, 0x00, 0x00, 0x00,
      0xff, 0xd9,
    ]);
    expect(readJpegExifOrientation(exifOrientedJpeg)).toBe(6);
    const exifImageAnalysis = applyImageOrientationMetadata(parseFfprobeOutput(JSON.stringify({
      streams: [
        {
          codec_type: 'video',
          codec_name: 'mjpeg',
          width: 96,
          height: 160,
          sample_aspect_ratio: '1:1',
        },
      ],
    }), 'image/jpeg'), 'image/jpeg', exifOrientedJpeg);
    expect(exifImageAnalysis.width).toBe(160);
    expect(exifImageAnalysis.height).toBe(96);
    expect(exifImageAnalysis.codedWidth).toBe(96);
    expect(exifImageAnalysis.codedHeight).toBe(160);
    expect(exifImageAnalysis.exifOrientation).toBe(6);
    expect(exifImageAnalysis.rotation).toBe(90);
  });

