  it('classifies remote package media URI schemes as external references before copy', () => {
    const project: EditorProject = {
      ...createDefaultEditorProject(),
      id: 'remote-package-media-project',
      name: 'Remote Package Media Project',
      assets: [
        {
          id: 'asset-remote-clip',
          name: 'Remote archive clip',
          kind: 'video',
          source: 's3://bucket/client/camera.mov',
          duration: 5,
          width: 1920,
          height: 1080,
          fps: 30,
        },
        {
          id: 'asset-invalid-path-clip',
          name: 'Invalid path clip',
          kind: 'video',
          source: `E:/media/${String.fromCharCode(0)}camera.mov`,
          duration: 3,
          width: 1280,
          height: 720,
          fps: 30,
        },
      ],
      tracks: [],
      markers: [],
      captions: [],
    };
    const manifest = buildProjectPackageMediaManifest(project, {
      generatedAt: '2026-06-12T00:03:00.000Z',
    });

    expect(classifyPackageMediaPath('file:///E:/media/camera.mov')).toBe('bundle-ready');
    expect(classifyPackageMediaPath('E:/media/camera.mov')).toBe('bundle-ready');
    expect(classifyPackageMediaPath('s3://bucket/client/camera.mov')).toBe('external-reference');
    expect(classifyPackageMediaPath('ftp://archive.example.test/camera.mov')).toBe('external-reference');
    expect(classifyPackageMediaPath('//cdn.example.test/camera.mov')).toBe('external-reference');
    expect(classifyPackageMediaPath('blob:http://localhost/camera')).toBe('volatile-source');
    expect(classifyPackageMediaPath(`E:/media/${String.fromCharCode(0)}camera.mov`)).toBe('copy-failed');
    expect(manifest).toMatchObject({
      bundleReadyCount: 0,
      externalCount: 1,
      missingCount: 2,
      volatileCount: 0,
      copyFailedCount: 1,
    });
    expect(manifest.entries.find((entry) => entry.assetId === 'asset-remote-clip' && entry.role === 'source')).toMatchObject({
      originalPath: 's3://bucket/client/camera.mov',
      packagePath: 'media/asset-remote-clip/source-camera.mov',
      status: 'external-reference',
      requiredForRender: true,
    });
    expect(manifest.entries.find((entry) => entry.assetId === 'asset-remote-clip' && entry.role === 'render')).toMatchObject({
      originalPath: '',
      status: 'missing',
      requiredForRender: true,
    });
    expect(manifest.entries.find((entry) => entry.assetId === 'asset-invalid-path-clip' && entry.role === 'source')).toMatchObject({
      status: 'copy-failed',
      requiredForRender: true,
    });
    expect(manifest.warnings).toEqual(expect.arrayContaining([
      'Remote archive clip uses external source media (s3://bucket/client/camera.mov) that will remain an external reference.',
      'Remote archive clip is missing required render path; relink or reimport before portable export.',
      'Invalid path clip required source media could not be copied into the portable package; relink or re-export before package import.',
    ]));
    expect(summarizeProjectPackageMediaReadiness(manifest)).toBe('4 media manifest entries need review, relink, or reimport before a portable package is complete.');
  });

  it('deduplicates colliding package media paths after asset and file name sanitization', () => {
    const project: EditorProject = {
      ...createDefaultEditorProject(),
      id: 'colliding-package-media-project',
      name: 'Colliding Package Media Project',
      assets: [
        {
          id: 'asset/camera',
          name: 'Camera A',
          kind: 'video',
          source: 'E:/media/camera.mov',
          renderPath: 'E:/media/camera-render.mov',
          duration: 5,
          width: 1920,
          height: 1080,
          fps: 30,
        },
        {
          id: 'asset:camera',
          name: 'Camera B',
          kind: 'video',
          source: 'E:/media/camera.mov',
          renderPath: 'E:/media/camera-render.mov',
          duration: 5,
          width: 1920,
          height: 1080,
          fps: 30,
        },
      ],
      tracks: [],
      markers: [],
      captions: [],
    };
    const manifest = buildProjectPackageMediaManifest(project, {
      generatedAt: '2026-06-12T00:04:00.000Z',
    });
    const packagePaths = manifest.entries.map((entry) => entry.packagePath);

    expect(new Set(packagePaths).size).toBe(packagePaths.length);
    expect(manifest.entries.find((entry) => entry.assetId === 'asset/camera' && entry.role === 'source')).toMatchObject({
      packagePath: 'media/asset_camera/source-camera.mov',
    });
    expect(manifest.entries.find((entry) => entry.assetId === 'asset:camera' && entry.role === 'source')).toMatchObject({
      packagePath: 'media/asset_camera/source-camera-2.mov',
    });
    expect(manifest.entries.find((entry) => entry.assetId === 'asset:camera' && entry.role === 'render')).toMatchObject({
      packagePath: 'media/asset_camera/render-camera-render-2.mov',
    });

    const duplicatePathRewrite = rewriteProjectMediaPathsForPackageImport(project, {
      ...manifest,
      entries: manifest.entries.map((entry) => (
        entry.assetId === 'asset:camera' && entry.role === 'source'
          ? { ...entry, packagePath: 'media/asset_camera/source-camera.mov' }
          : entry
      )),
    }, {
      packageRoot: '/imports/colliding-package',
    });

    expect(duplicatePathRewrite.project.assets.find((asset) => asset.id === 'asset/camera')).toMatchObject({
      source: '/imports/colliding-package/media/asset_camera/source-camera.mov',
    });
    expect(duplicatePathRewrite.project.assets.find((asset) => asset.id === 'asset:camera')).toMatchObject({
      source: 'E:/media/camera.mov',
      renderPath: '/imports/colliding-package/media/asset_camera/render-camera-render-2.mov',
    });
    expect(duplicatePathRewrite.warnings).toEqual(expect.arrayContaining([
      'Camera B source media reuses package path media/asset_camera/source-camera.mov; skipped to avoid rewriting multiple assets to the same packaged file.',
    ]));
  });

