  it('uses the Electron project package bridge before browser JSON fallback', async () => {
    const project = createDefaultEditorProject();
    const plan = resolveProjectPackageExportPlan(project);
    const calls: unknown[] = [];
    const globalWithWindow = globalThis as typeof globalThis & { window?: unknown };
    const previousWindow = globalWithWindow.window;

    Object.defineProperty(globalThis, 'window', {
      configurable: true,
      value: {
        danbiEditor: {
          projects: {
            exportPackage: async (request: unknown) => {
              calls.push(request);
              return {
                packageDirectory: '.danbi/packages/Danbi-Studio-AI-Edit',
                projectFilePath: '.danbi/packages/Danbi-Studio-AI-Edit/project.danbi-project.json',
                copiedMedia: [
                  {
                    assetId: 'asset-interview',
                    role: 'source',
                    originalPath: '/media/interview-master.mp4',
                    sourcePath: 'public/media/interview-master.mp4',
                    packagePath: 'media/asset-interview/source-interview-master.mp4',
                    targetPath: '.danbi/packages/Danbi-Studio-AI-Edit/media/asset-interview/source-interview-master.mp4',
                    status: 'copied',
                    bytes: 12,
                  },
                ],
                warnings: [],
              };
            },
          },
        },
      },
    });

    try {
      const result = await exportProjectPackageBestAvailable(project, plan);

      expect(result).toMatchObject({
        mode: 'electron-folder',
        status: 'Project package exported to .danbi/packages/Danbi-Studio-AI-Edit with 1 media file',
      });
      expect(calls).toEqual([{ project, packageDirectory: plan.packageDirectory }]);
    } finally {
      if (previousWindow === undefined) {
        Reflect.deleteProperty(globalWithWindow, 'window');
      } else {
        Object.defineProperty(globalThis, 'window', {
          configurable: true,
          value: previousWindow,
        });
      }
    }
  });

