  it('controls render jobs through the Electron render bridge before HTTP fallback', async () => {
    const project = createDefaultEditorProject();
    const plan = buildFfmpegRenderPlan(project, 'profile-short-vertical', 'E:/renders/client-final.mp4');
    const baseJob = {
      id: 'render-job-bridge',
      status: 'running' as const,
      progress: 42,
      priority: 6,
      outputPath: 'E:/renders/client-final.mp4',
      stderrTail: '',
      plan,
    };
    const calls: Array<{ method: string; payload: unknown }> = [];
    const globalWithWindow = globalThis as typeof globalThis & { window?: unknown };
    const previousWindow = globalWithWindow.window;
    const previousFetch = globalThis.fetch;

    Object.defineProperty(globalThis, 'window', {
      configurable: true,
      value: {
        danbiEditor: {
          render: {
            plan: async (request: unknown) => {
              calls.push({ method: 'plan', payload: request });
              return plan;
            },
            getJob: async (id: string) => {
              calls.push({ method: 'getJob', payload: id });
              return { job: baseJob };
            },
            cancelJob: async (id: string) => {
              calls.push({ method: 'cancelJob', payload: id });
              return { job: { ...baseJob, status: 'cancelled' as const, progress: 100 } };
            },
            retryJob: async (id: string, retry?: number | { priority?: number }) => {
              const priority = typeof retry === 'number' ? retry : retry?.priority;
              calls.push({ method: 'retryJob', payload: { id, ...(typeof retry === 'number' ? { priority: retry } : retry) } });
              return { job: { ...baseJob, id: 'render-job-retry', status: 'queued' as const, progress: 0, priority: priority ?? 0 } };
            },
            queue: async (request: { priority: number }) => {
              calls.push({ method: 'queue', payload: request });
              return { job: { ...baseJob, status: 'queued' as const, progress: 0, priority: request.priority } };
            },
            direct: async (request: { outputPath?: string }) => {
              calls.push({ method: 'direct', payload: request });
              return { outputPath: request.outputPath ?? plan.outputPath, plan };
            },
          },
        },
      },
    });
    Object.defineProperty(globalThis, 'fetch', {
      configurable: true,
      value: async () => {
        throw new Error('HTTP fetch should not be used when the Electron render bridge is available.');
      },
    });

    try {
      await expect(fetchServerRenderPlanFromRenderer({
        project,
        profileId: 'profile-short-vertical',
        outputPath: 'E:/renders/client-final.mp4',
      })).resolves.toBe(plan);
      await expect(fetchRenderJobFromRenderer('render-job-bridge')).resolves.toEqual(baseJob);
      await expect(cancelRenderJobFromRenderer('render-job-bridge')).resolves.toMatchObject({
        status: 'cancelled',
        progress: 100,
      });
      await expect(retryRenderJobFromRenderer('render-job-bridge', {
        project,
        profileId: 'profile-short-vertical',
        outputPath: 'E:/renders/client-final.mp4',
        priority: 8,
      })).resolves.toMatchObject({
        id: 'render-job-retry',
        status: 'queued',
        priority: 8,
      });
      await expect(queueRenderJobFromRenderer({
        project,
        profileId: 'profile-short-vertical',
        outputPath: 'E:/renders/client-final.mp4',
        priority: 5,
      })).resolves.toMatchObject({
        status: 'queued',
        priority: 5,
      });
      await expect(renderProjectNowFromRenderer({
        project,
        profileId: 'profile-short-vertical',
        outputPath: 'E:/renders/client-final.mp4',
      })).resolves.toEqual({
        outputPath: 'E:/renders/client-final.mp4',
        plan,
      });
      expect(calls.map((call) => call.method)).toEqual([
        'plan',
        'getJob',
        'cancelJob',
        'retryJob',
        'queue',
        'direct',
      ]);
      expect(calls[0].payload).toMatchObject({
        encoderPreference: 'auto',
        outputPath: 'E:/renders/client-final.mp4',
      });
      expect(calls[3].payload).toMatchObject({
        id: 'render-job-bridge',
        priority: 8,
        profileId: 'profile-short-vertical',
        outputPath: 'E:/renders/client-final.mp4',
      });
    } finally {
      if (previousWindow === undefined) {
        Reflect.deleteProperty(globalWithWindow, 'window');
      } else {
        Object.defineProperty(globalThis, 'window', {
          configurable: true,
          value: previousWindow,
        });
      }
      Object.defineProperty(globalThis, 'fetch', {
        configurable: true,
        value: previousFetch,
      });
    }
  });

