  it('aborts renderer render job HTTP fallback polling with caller signals', async () => {
    const globalWithWindow = globalThis as typeof globalThis & { window?: unknown };
    const previousWindow = globalWithWindow.window;
    const previousFetch = globalThis.fetch;
    const controller = new AbortController();
    const calls: Array<{ input: string; init?: RequestInit }> = [];

    Object.defineProperty(globalThis, 'window', {
      configurable: true,
      value: {},
    });
    Object.defineProperty(globalThis, 'fetch', {
      configurable: true,
      value: async (input: RequestInfo | URL, init?: RequestInit) => new Promise<Response>((_resolve, reject) => {
        calls.push({ input: String(input), init });
        init?.signal?.addEventListener('abort', () => {
          reject(new Error('render job polling aborted'));
        }, { once: true });
      }),
    });

    try {
      const request = expect(fetchRenderJobFromRenderer('render-job-http', {
        signal: controller.signal,
      })).rejects.toThrow('render job polling aborted');

      controller.abort();
      await request;

      expect(calls).toHaveLength(1);
      expect(calls[0].input).toBe('/api/editor/render-jobs/render-job-http');
      expect(calls[0].init?.signal?.aborted).toBe(true);
    } finally {
      Object.defineProperty(globalThis, 'fetch', {
        configurable: true,
        value: previousFetch,
      });
      if (previousWindow === undefined) {
        Reflect.deleteProperty(globalWithWindow, 'window');
      } else {
        Object.defineProperty(globalThis, 'window', {
          configurable: true,
          value: previousWindow,
        });
      }
    }
  });

