  it('times out browser media metadata probing without blocking imports', async () => {
    const globalWithBrowserApis = globalThis as typeof globalThis & {
      document?: unknown;
      window?: unknown;
    };
    const previousDocument = globalWithBrowserApis.document;
    const previousWindow = globalWithBrowserApis.window;
    let loadCalled = false;
    let removedSource = false;

    Object.defineProperty(globalThis, 'window', {
      configurable: true,
      value: {
        setTimeout,
        clearTimeout,
      },
    });
    Object.defineProperty(globalThis, 'document', {
      configurable: true,
      value: {
        createElement: () => ({
          duration: Number.NaN,
          videoWidth: 0,
          videoHeight: 0,
          preload: '',
          src: '',
          onloadedmetadata: null,
          onerror: null,
          removeAttribute: (name: string) => {
            removedSource = name === 'src';
          },
          load: () => {
            loadCalled = true;
          },
        }),
      },
    });

    try {
      const videoFile = {
        name: 'stalled.mp4',
        type: 'video/mp4',
        size: 2048,
      } as File;
      const input = await readMediaInput(videoFile, 'blob:stalled-preview', { metadataTimeoutMs: 1 });

      expect(input).toMatchObject({
        name: 'stalled.mp4',
        mimeType: 'video/mp4',
        size: 2048,
        source: 'blob:stalled-preview',
      });
      expect(input).not.toHaveProperty('duration');
      expect(loadCalled).toBe(true);
      expect(removedSource).toBe(true);
    } finally {
      if (previousDocument === undefined) {
        Reflect.deleteProperty(globalThis, 'document');
      } else {
        Object.defineProperty(globalThis, 'document', {
          configurable: true,
          value: previousDocument,
        });
      }
      if (previousWindow === undefined) {
        Reflect.deleteProperty(globalThis, 'window');
      } else {
        Object.defineProperty(globalThis, 'window', {
          configurable: true,
          value: previousWindow,
        });
      }
    }
  });

  it('persists editor projects through the Electron native project repository', async () => {
    const tempRoot = await mkdtemp(joinPath(tmpdir(), 'danbi-electron-projects-'));

    try {
      const repository = createNativeProjectRepository({ rootDir: tempRoot });
      const project = {
        ...createDefaultEditorProject(),
        id: 'client/electron-project',
        name: 'Electron Project Store',
      };

      await expect(repository.list()).resolves.toEqual({ projects: [] });
      const saved = await repository.save(project);
      const loaded = await repository.load(project.id);
      const listed = await repository.list();

      expect(saved.project).toMatchObject({
        id: project.id,
        name: 'Electron Project Store',
      });
      expect(loaded?.project).toMatchObject({
        id: project.id,
        name: 'Electron Project Store',
      });
      expect(listed.projects).toHaveLength(1);
      expect(listed.projects[0]).toMatchObject({
        id: project.id,
        name: 'Electron Project Store',
      });
      const savedProjectFilenames = (await readdir(tempRoot)).filter((filename) => filename.endsWith('.json'));
      expect(savedProjectFilenames).toHaveLength(1);
      await expect(readFile(joinPath(tempRoot, savedProjectFilenames[0]), 'utf8')).resolves.toContain('Electron Project Store');
      await expect(repository.save({
        ...project,
        id: 'invalid/electron-project',
        tracks: [
          {
            ...project.tracks[0],
            clips: [
              {
                ...project.tracks[0].clips[0],
                assetId: 'missing-asset',
              },
            ],
          },
        ],
      })).rejects.toThrow('Cannot save native editor project because its JSON is invalid');
      await expect(repository.load('invalid/electron-project')).resolves.toBeUndefined();
      await expect(repository.delete(project.id)).resolves.toEqual({
        deleted: true,
        id: project.id,
      });
      await expect(repository.load(project.id)).resolves.toBeUndefined();
    } finally {
      await rm(tempRoot, { recursive: true, force: true });
    }
  });

