  it('registers extension commands and hooks only when the built-in manifest contract is satisfied', () => {
    const project = createDefaultEditorProject();
    const restrictedProject: EditorProject = {
      ...project,
      plugins: project.plugins.map((plugin) => (
        plugin.id === 'plugin-ffmpeg-renderer'
          ? {
              ...plugin,
              permissions: plugin.permissions.filter((permission) => permission !== 'render'),
              contributes: plugin.contributes.filter((contribution) => contribution !== 'exporter'),
            }
          : plugin
      )),
    };
    const restrictedHost = buildExtensionHostSnapshot(restrictedProject);
    const restrictedInvoke = invokeExtensionCommand(restrictedProject, {
      project: restrictedProject,
      extensionId: 'plugin-ffmpeg-renderer',
      command: 'danbi.ffmpeg.inspectRenderContext',
    });
    const restrictedHooks = runExtensionRenderHooks({
      project: restrictedProject,
      profileId: 'profile-youtube-4k',
    });
    const spoofedEntryProject: EditorProject = {
      ...project,
      plugins: project.plugins.map((plugin) => (
        plugin.id === 'plugin-ffmpeg-renderer'
          ? { ...plugin, entry: 'plugins/ffmpeg-renderer/../escape.ts' }
          : plugin
      )),
    };
    const spoofedHost = buildExtensionHostSnapshot(spoofedEntryProject);
    const spoofedInvoke = invokeExtensionCommand(spoofedEntryProject, {
      project: spoofedEntryProject,
      extensionId: 'plugin-ffmpeg-renderer',
      command: 'danbi.ffmpeg.inspectRenderContext',
    });
    const externalPluginProject: EditorProject = {
      ...project,
      plugins: [
        ...project.plugins,
        {
          id: 'plugin-external-look-pack',
          name: 'External Look Pack',
          version: '0.1.0',
          entry: 'plugins/external-look-pack/index.js',
          permissions: ['project'],
          contributes: ['effect', 'analyzer'],
        },
      ],
    };
    const externalHost = buildExtensionHostSnapshot(externalPluginProject);
    const externalInvoke = invokeExtensionCommand(externalPluginProject, {
      project: externalPluginProject,
      extensionId: 'plugin-external-look-pack',
      command: 'external.looks.inspect',
    });

    expect(restrictedHost.commands.map((command) => command.id)).not.toContain('danbi.ffmpeg.inspectRenderContext');
    expect(restrictedHost.renderHooks.map((hook) => hook.id)).not.toContain('danbi.ffmpeg.beforeRender');
    expect(restrictedHost.warnings).toEqual(expect.arrayContaining([
      expect.stringContaining('Extension plugin-ffmpeg-renderer command danbi.ffmpeg.inspectRenderContext was not registered'),
      expect.stringContaining('it requires render permission'),
      expect.stringContaining('it requires exporter contribution'),
      expect.stringContaining('Extension plugin-ffmpeg-renderer render hook danbi.ffmpeg.beforeRender was not registered'),
    ]));
    expect(restrictedInvoke).toMatchObject({
      handled: false,
      warnings: expect.arrayContaining([
        expect.stringContaining('Command danbi.ffmpeg.inspectRenderContext is not registered'),
        expect.stringContaining('it requires render permission'),
      ]),
    });
    expect(restrictedHooks.handledHookCount).toBe(1);
    expect(restrictedHooks.warnings).toEqual(expect.arrayContaining([
      expect.stringContaining('Extension plugin-ffmpeg-renderer render hook danbi.ffmpeg.beforeRender was not registered'),
    ]));
    expect(spoofedHost.commands.map((command) => command.id)).not.toContain('danbi.ffmpeg.inspectRenderContext');
    expect(spoofedHost.renderHooks.map((hook) => hook.id)).not.toContain('danbi.ffmpeg.beforeRender');
    expect(spoofedHost.blockedPlugins).toEqual([
      expect.objectContaining({
        pluginId: 'plugin-ffmpeg-renderer',
        reason: expect.stringContaining('does not match the registered built-in entry'),
      }),
    ]);
    expect(spoofedInvoke).toMatchObject({
      handled: false,
      warnings: expect.arrayContaining([
        expect.stringContaining('External plugin loading is disabled'),
      ]),
    });
    expect(externalHost.commands.map((command) => command.sourcePluginId)).not.toContain('plugin-external-look-pack');
    expect(externalHost.renderHooks.map((hook) => hook.sourcePluginId)).not.toContain('plugin-external-look-pack');
    expect(externalHost.sandboxes).toEqual(expect.arrayContaining([
      expect.objectContaining({
        pluginId: 'plugin-external-look-pack',
        status: 'manifest-only',
        runtime: 'external-process-command',
        declaredApis: ['effect', 'analyzer'],
        executableApis: ['command'],
        reason: expect.stringContaining('reviewed process-isolated command execution'),
      }),
    ]));
    expect(externalHost.warnings).toEqual(expect.arrayContaining([
      expect.stringContaining('Extension plugin-external-look-pack is available only through reviewed external sandbox commands'),
    ]));
    expect(externalInvoke).toMatchObject({
      handled: false,
      warnings: expect.arrayContaining([
        expect.stringContaining('Command external.looks.inspect is not registered'),
        expect.stringContaining('reviewed external sandbox commands'),
      ]),
    });
  });

  it('commits timeline transactions with serialized no-op detection and undo redo state', () => {
    const project = createDefaultEditorProject();
    const noOp = commitTimelineEditTransaction({
      project,
      history: [],
      future: [],
    }, {
      label: 'No-op copy',
      update: (current) => ({ ...current }),
    });

    expect(noOp).toMatchObject({
      committed: false,
      status: 'No-op copy',
      changedClipIds: [],
    });
    expect(noOp.history).toHaveLength(0);

    const committed = commitTimelineClipPatchTransaction({
      project,
      history: [],
      future: [],
    }, {
      label: 'Patch intro clip',
      clipId: 'clip-interview-1',
      patch: {
        name: '  Trimmed intro  ',
        start: -20,
        duration: 0.01,
      },
      selection: {
        selectedClipId: 'clip-interview-1',
        selectedClipIds: ['clip-interview-1'],
        playhead: 2,
      },
    });
    const patchedClip = committed.project.tracks.flatMap((track) => track.clips).find((clip) => clip.id === 'clip-interview-1');

    expect(committed.committed).toBe(true);
    expect(committed.status).toBe('Patch intro clip');
    expect(committed.history).toEqual([project]);
    expect(committed.future).toEqual([]);
    expect(committed.changedClipIds).toEqual(['clip-interview-1']);
    expect(committed.previousSelection).toMatchObject({ selectedClipId: 'clip-interview-1', playhead: 2 });
    expect(patchedClip).toMatchObject({
      name: 'Trimmed intro',
      start: 0,
      duration: 0.25,
    });

    const undone = undoTimelineEditTransaction(committed);
    expect(undone).toMatchObject({
      changed: true,
      project,
      history: [],
      status: 'Undo',
      selectedClipId: 'clip-interview-1',
    });
    expect(undone.future).toEqual([committed.project]);

    const undoneWithPreferredSelection = undoTimelineEditTransaction(committed, { selectedClipId: 'clip-interview-2' });
    expect(undoneWithPreferredSelection.selectedClipId).toBe('clip-interview-2');

    const undoneWithMissingSelection = undoTimelineEditTransaction(committed, { selectedClipId: 'missing-clip' });
    expect(undoneWithMissingSelection.selectedClipId).toBe('clip-interview-1');

    const redone = redoTimelineEditTransaction(undone);
    expect(redone).toMatchObject({
      changed: true,
      project: committed.project,
      history: [project],
      future: [],
      status: 'Redo',
      selectedClipId: 'clip-interview-1',
    });

    const redoneWithPreferredSelection = redoTimelineEditTransaction(undone, { selectedClipId: 'clip-interview-2' });
    expect(redoneWithPreferredSelection.selectedClipId).toBe('clip-interview-2');
  });

