  it('edits, duplicates, and removes export profiles safely', () => {
    const project = createDefaultEditorProject();
    const updated = updateExportProfile(project, 'profile-youtube-4k', {
      label: '  Client Master  ',
      purpose: 'master',
      container: 'mov',
      codec: 'prores',
      width: 99999,
      height: -20,
      fps: 999,
      videoBitrateMbps: -4,
      audioBitrateKbps: 9999,
      ffmpegPreset: 'slow',
      crf: 99,
    });
    const profile = updated.exportProfiles.find((item) => item.id === 'profile-youtube-4k');
    const duplicate = duplicateExportProfile(updated, 'profile-youtube-4k');
    const duplicateAgain = duplicateExportProfile(duplicate.project, 'profile-youtube-4k');
    const removed = removeExportProfile(duplicateAgain.project, duplicate.profile.id);

    expect(profile).toMatchObject({
      label: 'Client Master',
      container: 'mov',
      codec: 'prores',
      width: 8192,
      height: 16,
      fps: 240,
      videoBitrateMbps: 0.5,
      audioBitrateKbps: 1024,
      ffmpegPreset: 'slow',
      crf: 51,
    });
    const webmProfileProject = updateExportProfile(project, 'profile-youtube-4k', {
      container: 'webm',
      codec: 'h264',
    });
    const webmProfile = webmProfileProject.exportProfiles.find((item) => item.id === 'profile-youtube-4k');
    const oddDimensionProject = updateExportProfile(project, 'profile-youtube-4k', {
      width: 1279,
      height: 721,
    });
    const oddDimensionProfile = oddDimensionProject.exportProfiles.find((item) => item.id === 'profile-youtube-4k');
    expect(webmProfile).toMatchObject({
      container: 'webm',
      codec: 'av1',
    });
    expect(oddDimensionProfile).toMatchObject({
      width: 1280,
      height: 722,
    });
    expect(getExportProfileCodecOptions('webm')).toEqual(['av1']);
    expect(getExportProfileCodecOptions('mov')).toEqual(['h264', 'h265', 'prores']);
    expect(duplicate.profile).toMatchObject({
      id: 'profile-youtube-4k-copy',
      label: 'Client Master Copy',
    });
    expect(duplicateAgain.profile.id).toBe('profile-youtube-4k-copy-2');
    expect(removed.exportProfiles.some((item) => item.id === duplicate.profile.id)).toBe(false);
    expect(updateExportProfile(project, 'profile-youtube-4k', project.exportProfiles[0])).toBe(project);
    expect(() => updateExportProfile(project, 'missing-profile', { label: 'Missing' })).toThrow('Export profile not found');
    expect(() => removeExportProfile({
      ...project,
      exportProfiles: [project.exportProfiles[0]],
    }, project.exportProfiles[0].id)).toThrow('At least one export profile is required.');
  });

  it('resolves project settings mutations outside the editor page shell', () => {
    const project = createDefaultEditorProject();
    const selectedExportProfile = project.exportProfiles[0];

    const projectSettingsPlan = resolveProjectSettingsChangePlan({
      name: '  Client Cut  ',
      width: 1001,
    });
    expect(projectSettingsPlan).toMatchObject({
      canCommit: true,
      commitLabel: 'Project settings updated',
    });
    const settingsResult = projectSettingsPlan.apply!(project);
    expect(settingsResult.project).toMatchObject({
      name: 'Client Cut',
      width: 1002,
    });

    const exportPatchPlan = resolveExportProfilePatchPlan({
      selectedExportProfile,
      patch: { label: ' Review Master ' },
    });
    expect(exportPatchPlan).toMatchObject({
      canCommit: true,
      commitLabel: 'Export profile updated',
    });
    const patchedExportResult = exportPatchPlan.apply!(project);
    expect(patchedExportResult.project.exportProfiles[0].label).toBe('Review Master');
    expect(resolveExportProfilePatchPlan({
      selectedExportProfile: undefined,
      patch: { label: 'Missing' },
    })).toEqual({
      canCommit: false,
      status: 'Select an export profile first',
    });

    const duplicatePlan = resolveDuplicateExportProfilePlan(selectedExportProfile);
    const duplicateResult = duplicatePlan.apply!(patchedExportResult.project);
    expect(duplicatePlan).toMatchObject({
      canCommit: true,
      commitLabel: 'Export profile duplicated',
    });
    expect(duplicateResult.nextSelectedExportProfileId).toBe('profile-youtube-4k-copy');
    expect(duplicateResult.project.exportProfiles.at(-1)?.label).toBe('Review Master Copy');

    const duplicateProfile = duplicateResult.project.exportProfiles.find((profile) => (
      profile.id === duplicateResult.nextSelectedExportProfileId
    ));
    const removePlan = resolveRemoveExportProfilePlan({
      project: duplicateResult.project,
      selectedExportProfile: duplicateProfile,
    });
    const removeResult = removePlan.apply!(duplicateResult.project);
    expect(removePlan).toMatchObject({
      canCommit: true,
      commitLabel: 'Export profile removed',
    });
    expect(removeResult.nextSelectedExportProfileId).toBe('profile-youtube-4k');
    expect(removeResult.project.exportProfiles.some((profile) => profile.id === duplicateProfile?.id)).toBe(false);
    expect(resolveDuplicateExportProfilePlan(undefined)).toEqual({
      canCommit: false,
      status: 'Select an export profile first',
    });

    const masterAudioPlan = resolveMasterAudioSettingsChangePlan({
      loudnessLufs: -11,
      truePeakDb: -0.5,
    });
    expect(masterAudioPlan).toMatchObject({
      canCommit: true,
      commitLabel: 'Master audio updated',
    });
    expect(resolveMasterAudioSettings(masterAudioPlan.apply!(project).project)).toEqual({
      loudnessLufs: -11,
      truePeakDb: -0.5,
    });
  });

