  it('uses durable local output storage for default FFmpeg render outputs', async () => {
    const tempRoot = await mkdtemp(joinPath(tmpdir(), 'danbi-render-output-root-'));
    const previousLocalDataRoot = process.env.DANBI_LOCAL_DATA_ROOT;
    const previousElectronUserData = process.env.DANBI_ELECTRON_USER_DATA;

    try {
      const localDataRoot = joinPath(tempRoot, 'local-data');
      process.env.DANBI_LOCAL_DATA_ROOT = localDataRoot;
      delete process.env.DANBI_ELECTRON_USER_DATA;
      const project = createDefaultEditorProject();
      const capabilities = {
        ffmpegPath: 'ffmpeg',
        detectedAt: '2026-06-17T00:00:00.000Z',
        encoders: ['libx264'],
        hardwareEncoders: [],
        warnings: [],
      };

      const enginePreflight = await buildFfmpegEnginePreflight({
        project,
        profileId: 'profile-youtube-4k',
        encoderPreference: 'software',
        capabilities,
      });
      const [headlessRequest] = buildHeadlessRenderRequests({
        project,
        batchId: 'durable-default',
      });

      expect(enginePreflight.projectId).toBe(project.id);
      expect((await stat(joinPath(localDataRoot, 'outputs'))).isDirectory()).toBe(true);
      await expect(stat(joinPath(tempRoot, 'public', 'outputs'))).rejects.toMatchObject({ code: 'ENOENT' });
      expect(getDefaultHeadlessOutputDir()).toBe(joinPath(localDataRoot, 'outputs'));
      expect(headlessRequest.outputPath).toBe(joinPath(localDataRoot, 'outputs', 'danbi-demo-project-profile-youtube-4k-durable-default.mp4'));
    } finally {
      restoreEnvValue('DANBI_LOCAL_DATA_ROOT', previousLocalDataRoot);
      restoreEnvValue('DANBI_ELECTRON_USER_DATA', previousElectronUserData);
      await rm(tempRoot, { recursive: true, force: true });
    }
  });

