    expect(() => parseRenderWorkerHandoffManifest(JSON.stringify({
      kind: 'not-danbi',
      schemaVersion: 1,
      jobs: [],
    }))).toThrow('Invalid Danbi render worker handoff manifest');

    let tick = 0;
