  it('keeps track mute and solo playback policy in FFmpeg render plans', () => {
    const project = createDefaultEditorProject();
    const mutedARollPlan = buildFfmpegRenderPlan(
      toggleTrackState(project, 'track-v1', 'muted'),
      'profile-youtube-4k',
      'renders/muted-a-roll.mp4',
    );
    const lockedARollPlan = buildFfmpegRenderPlan(
      toggleTrackState(project, 'track-v1', 'locked'),
      'profile-youtube-4k',
      'renders/locked-a-roll.mp4',
    );
    const musicSoloPlan = buildFfmpegRenderPlan(
      toggleTrackState(project, 'track-a1', 'solo'),
      'profile-youtube-4k',
      'renders/music-solo.mp4',
    );

    expect(mutedARollPlan.inputs.map((input) => input.clipId)).not.toContain('clip-interview-1');
    expect(mutedARollPlan.inputs.map((input) => input.clipId)).not.toContain('clip-interview-2');
    expect(mutedARollPlan.inputs.map((input) => input.clipId)).toContain('clip-music-1');
    expect(mutedARollPlan.filterGraph.some((filter) => filter.includes('drawtext'))).toBe(true);

    expect(lockedARollPlan.inputs.map((input) => input.clipId)).toEqual(expect.arrayContaining([
      'clip-interview-1',
      'clip-interview-2',
      'clip-music-1',
    ]));
    const lockedInterviewInput = lockedARollPlan.inputs.find((input) => input.clipId === 'clip-interview-1');
    expect(lockedInterviewInput).toBeDefined();
    expect(lockedARollPlan.filterGraph.some((filter) => filter.startsWith(`[${lockedInterviewInput!.index}:a]`))).toBe(true);

    const musicSoloInputs = new Map(musicSoloPlan.inputs.map((input) => [input.clipId, input]));
    const interviewInput = musicSoloInputs.get('clip-interview-1');
    const workflowInput = musicSoloInputs.get('clip-interview-2');
    const musicInput = musicSoloInputs.get('clip-music-1');
    expect(interviewInput).toBeDefined();
    expect(workflowInput).toBeDefined();
    expect(musicInput).toBeDefined();

    expect(musicSoloPlan.filterGraph.some((filter) => filter.startsWith(`[${musicInput!.index}:a]`))).toBe(true);
    expect(musicSoloPlan.filterGraph.some((filter) => filter.startsWith(`[${interviewInput!.index}:a]`))).toBe(false);
    expect(musicSoloPlan.filterGraph.some((filter) => filter.startsWith(`[${workflowInput!.index}:a]`))).toBe(false);
    expect(musicSoloPlan.filterGraph.some((filter) => filter.includes('overlay='))).toBe(true);
    expect(musicSoloPlan.command).toEqual(expect.arrayContaining(['-map', '[vout]', '-map', '[aout]']));
  });

