  it('writes FFmpeg render sidecar files for chapter metadata', async () => {
    const tempRoot = await mkdtemp(joinPath(tmpdir(), 'danbi-render-sidecars-'));

    try {
      const plan = buildFfmpegRenderPlan(
        createDefaultEditorProject(),
        'profile-youtube-4k',
        joinPath(tempRoot, 'chaptered-export.mp4'),
      );
      await prepareFfmpegRenderPlanSidecarFiles(plan);
      const sidecarDirectoryFiles = await readdir(tempRoot);

      expect(plan.chapterMetadata?.path).toBe(joinPath(tempRoot, 'chaptered-export.mp4.ffmetadata'));
      await expect(readFile(plan.chapterMetadata!.path, 'utf8')).resolves.toContain('title=Hook');
      await expect(readFile(plan.chapterMetadata!.path, 'utf8')).resolves.toContain('END=4000');
      expect(sidecarDirectoryFiles.some((filename) => filename.endsWith('.tmp'))).toBe(false);
    } finally {
      await rm(tempRoot, { recursive: true, force: true });
    }
  });

